align: center;\n  vertical-align: middle;\n  cursor: pointer;\n  border: 1px solid rgba(0, 0, 0, 0);\n  border-radius: 4px;\n  white-space: nowrap;\n  -webkit-user-select: none;\n  color: rgb(255, 255, 255);\n  background-color: rgb(92, 184, 92);\n  border-color: rgb(76, 174, 76);\n}',NULL,NULL,'text/css','2026-09-10 15:43:45','2026-09-10 15:43:45',NULL,NULL,'',NULL,0,NULL),(21,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'field','{% comment %}\n  This partial is by default used throughout the whole 3scale system.\n  You can find it in almost any form such as \'applications/edit\' or\n  \'signup\'. So be careful with any changes as it may break a lot.\n{% endcomment %}\n{% if field.read_only or field.hidden %}\n  {% continue %}\n{% endif %}\n\n{% if field.choices == present %}\n  <div class=\"form-group {% if field.required %} required {% else %} optional {% endif %}\"\n      id=\"{{ field.html_id }}_input\">\n      <label class=\"col-md-4 control-label\" for=\"{{ field.html_id }}_id\" >\n          {{ field.label }}\n          {% if field.required %} <abbr class=\"required\" title=\"required\">*</abbr> {% endif %}\n      </label>\n      <div class=\"col-md-6\">\n        <select name=\"{{ field.input_name }}\" id=\"{{ field.html_id }}_id\"\n                class=\"{{ field.errors | error_class }} form-control\">\n            <option/>\n            {% for choice in field.choices %}\n              <option {% if field.value == choice.id %} selected {% endif %}\n                value=\"{{choice.id}}\">{{choice.label}}</option>\n            {% endfor %}\n        </select>\n        {{ field.errors | inline_errors }}\n      </div>\n  </div>\n{% else %}\n  <div class=\"form-group {{ field.errors | error_class: \'has-error\' }}\">\n    <label class=\"col-md-4 control-label\" for=\"{{ field.html_id }}\">\n      {{ field.label }}\n      {% if field.required %} <abbr class=\"required\" title=\"required\">*</abbr> {% endif %}\n    </label>\n    <div class=\"col-md-6\">\n      <input type=\"text\"\n             name=\"{{ field.input_name }}\"\n             id=\"{{ field.html_id }}\"\n             value=\"{{ field.value }}\"\n             class=\"{{ field.errors | error_class }} form-control\" />\n      {{ field.errors | inline_errors }}\n    </div>\n  </div>\n{% endif %}\n',NULL,1,NULL,'2026-09-10 15:43:45','2026-09-10 15:43:45',NULL,NULL,'',NULL,0,'_field'),(22,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'shared/pagination','{% if pagination.pages > 1 %}\n	<ul class=\"pagination\">\n	  {% for part in pagination.parts %}\n	    <li class=\"{{ part.rel }} {% unless part.is_link %}disabled{% endunless %}\">\n	      <a rel=\"{{ part.rel }}\" href=\"{{ part.url }}\">{{ part.title }}</a>\n	    </li>\n	  {% endfor %}\n	</ul>\n{% endif %}\n',NULL,1,NULL,'2026-09-10 15:43:45','2026-09-10 15:43:45',NULL,NULL,'',NULL,0,'shared/_pagination'),(23,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'shared/swagger_ui','<div class=\"swagger-section\">\n    <div id=\"message-bar\" class=\"swagger-ui-wrap\">&nbsp;</div>\n    <div id=\"swagger-ui-container\" class=\"swagger-ui-wrap\"></div>\n</div>\n\n<div class=\'apidocs-param-tips apidocs-signin-message\' style=\'display:none;\'>\n    <p><a href=\'#\'>Sign in</a> to your account for quick access to useful values.</p>\n</div>\n\n<script type=\"text/javascript\">\n  (function () {\n    var url = \"{{provider.api_specs.first.url}}\";\n\n    window.swaggerUi = new SwaggerUi({\n      url: url,\n      dom_id: \'swagger-ui-container\',\n      supportedSubmitMethods: [\'get\', \'post\', \'put\', \'delete\', \'patch\'],\n      apisSorter: \'alpha\', // can also be a function\n      operationsSorter: \'method\', // can also be \'alpha\' or a function\n      onComplete: function(swaggerApi, swaggerUi) {\n        $(document.getElementById(swaggerUi.dom_id)).find(\'pre code\').each(function(i, e) {hljs.highlightBlock(e)})\n      },\n      docExpansion: \'list\',\n      transport: function (httpClient, obj) {\n        obj.url = obj.url.replace(/^http:\\/\\//i, \'https://\')\n        return httpClient.execute(obj)\n      }\n    });\n  }());\n</script>\n',NULL,1,NULL,'2026-09-10 15:43:45','2026-09-10 15:43:45',NULL,NULL,'',NULL,0,'shared/_swagger_ui'),(24,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'submenu','<div id=\"navbar-1\" class=\"navbar-collapse collapse\">\n\n  {% if current_user %}\n    {% unless current_account.requires_credit_card_now? %}\n      <ul class=\"nav navbar-nav\">\n\n        {% if provider.multiple_applications_allowed? %}\n          <li class=\"{% if urls.applications.active? %}active{% endif %}\">\n            <a href=\"{{ urls.applications }}\">{{ urls.applications.title }}</a>\n          </li>\n          {% elsif current_account.applications.first == present%}\n          {% assign app = current_account.applications.first %}\n          <li class=\"{% if app.url.active? %}active{% endif %}\">\n            <a href=\"{{ app.url }}\">API Credentials</a>\n          </li>\n          {% elsif current_user.can.create_application? %}\n          <li class=\"{% if url.new_application.active? %}active{% endif %}\">\n            <a href=\"{{ urls.new_application }}\">Get API Credentials</a>\n          </li>\n        {% else %}\n          <!-- You don\'t have any application neither can create one. Bad luck. -->\n        {% endif %}\n\n        {% assign live_apps_present = current_account.applications | map: \'state\' | any: \'live\' %}\n        {% if live_apps_present %}\n          <li class=\"{% if urls.stats.active? %}active{% endif %}\">\n            <a href=\"{{ urls.stats }}\">Statistics</a>\n          </li>\n        {% endif %}\n\n        {% if provider.multiple_services_allowed? %}\n          <li class=\"{% if urls.services.active? %}active{% endif %}\">\n            <a href=\"{{ urls.services }}\">{{ urls.services.title }}</a>\n          </li>\n        {% endif %}\n\n        <li><a class=\"{% if urls.docs.active? %}active{% endif %}\" href=\"/docs\">Documentation</a></li>\n\n      </ul>\n    {% endunless %}\n    <ul id=\"user_widget\" class=\"nav navbar-nav navbar-right\">\n      {% unless current_account.requires_credit_card_now? %}\n        <li class=\"{% if urls.messages_inbox.active? %}active{% endif %}\">\n          <a href=\"{{ urls.messages_inbox }}\">\n            Messages\n            {% if current_account.unread_messages.size > 0 %}\n              <span class=\"badge\">{{ current_account.unread_messages.size }}</span>\n            {% endif %}\n          </a>\n        </li>\n        <li class=\"{% if urls.account_overview.active? %}active{% endif %}\">\n          <a href=\"{{ urls.account_overview }}\">\n            <i class=\"fa fa-cogs\"></i>\n            Settings\n          </a>\n        </li>\n      {% endunless %}\n      <li>\n        <a id=\"sign-out-button\" class=\"pull-right sign-out\" title=\"Sign Out {{ current_user.username }}\" href=\"{{ urls.logout }}\">\n          <i class=\"fa fa-sign-out\"></i>\n        </a>\n      </li>\n    </ul>\n\n  {% else %}\n    <ul class=\"nav navbar-nav\">\n      <li><a href=\"/docs\">Documentation</a></li>\n      <li><a href=\"/#plans\">Plans</a></li>\n    </ul>\n    <ul class=\"nav navbar-nav navbar-right\">\n      <li>\n        <a href=\"{{ urls.login }}\" title=\"Login\">\n          Sign in\n        </a>\n      </li>\n    </ul>\n  {% endif %}\n</div>\n',NULL,1,NULL,'2026-09-10 15:43:45','2026-09-10 15:43:45',NULL,NULL,'',NULL,0,'_submenu'),(25,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'menu_item','<li class=\"{% if menu_item.current_or_subpath? %}active{% endif %}\">\n  <a href=\"{{ menu_item }}\">{{ menu_item.title }}</a>\n</li>\n',NULL,1,NULL,'2026-09-10 15:43:45','2026-09-10 15:43:45',NULL,NULL,'',NULL,0,'_menu_item'),(26,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'users_menu','<ul class=\"nav nav-tabs\">\n  {% unless current_account.requires_credit_card_now? %}\n    <li class=\"{% if urls.account_overview.active? %}active{% endif %}\">\n      <a href=\"{{ urls.account_overview }}\">Account Details</a>\n    </li>\n\n    {% if provider.account_management_enabled? %}\n      {% if current_user.admin? %}\n        {% include \'menu_item\' with urls.users %}\n      {% endif %}\n\n      {% if provider.multiple_users_allowed? %}\n        {% if current_user.admin? %}\n          {% include \'menu_item\' with urls.invitations %}\n        {% endif %}\n      {% endif %}\n    {% endif %}\n\n\n    {% if provider.account_plans_allowed? %}\n      {% include \'menu_item\' with urls.account_plans %}\n    {% endif %}\n  {%  endunless %}\n\n  {% if provider.finance_allowed? %}\n    {% unless current_account.requires_credit_card_now? %}\n      {% include \'menu_item\' with urls.invoices %}\n    {% endunless %}\n\n    {% if urls.payment_details %}\n      {% include \'menu_item\' with urls.payment_details %}\n    {% endif %}\n  {% endif %}\n\n</ul>\n',NULL,1,NULL,'2026-09-10 15:43:45','2026-09-10 15:43:45',NULL,NULL,'',NULL,0,'_users_menu'),(27,2,2,3,'CMS::Builtin::Page',NULL,'Dashboard','dashboards/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\" id=\"access-details\">\n      <div class=\"panel-heading\">\n        <i class=\"fa fa-key\"></i>\n        Credentials\n        {% if current_account.applications.size > 0 %}\n          <a class=\"pull-right\" href=\"{{ urls.applications }}\" title=\"inbox\">\n            <i class=\"fa fa-chevron-right\"></i>\n          </a>\n        {% endif %}\n      </div>\n      <div class=\"panel-body panel-footer\">\n        {% if current_account.applications.size == 0 %}\n          <a href=\"{{ urls.new_application }}\" class=\"btn btn-primary\">Create Application</a>\n        {% elsif current_account.applications.size >= 1 %}\n          {% assign app = current_account.applications.first %}\n\n          {% if app.user_key_mode? %}\n            <dl class=\"dl-horizontal\">\n              <dt>App name</dt>\n              <dd><a href=\"{{ app.url }}\">{{ app.name }}</a></dd>\n              <dt>Key</dt>\n              <dd>\n                <code>{{ app.user_key }}</code>\n                <p>Add this as a <code>user_key</code> parameter to your API calls to authenticate.</p>\n              </dd>\n            </dl>\n\n          {% elsif app.app_id_mode? %}\n            <dl class=\"dl-horizontal\">\n              <dt>App name</dt>\n              <dd><a href=\"{{ app.url }}\">{{ app.name }}</a></dd>\n              <dt>App ID</dt>\n              <dd><code>{{ app.application_id }}</code></dd>\n              <dt>Key</dt>\n              <dd><code>{{ app.keys.first }}</code></dd>\n            </dl>\n\n          {% elsif app.oauth_mode? %}\n            <dl class=\"dl-horizontal\">\n              <dt>App name</dt>\n              <dd><a href=\"{{ app.url }}\">{{ app.name }}</a></dd>\n              <dt>Client ID</dt>\n              <dd><code>{{ app.application_id }}</code></dd>\n              <dt>Client Secret</dt>\n              <dd><code>{{ app.keys.first }}</code></dd>\n            </dl>\n          {% endif %}\n\n          {% if app.trial? %}\n            <div class=\"alert alert-warning\">\n              <h3>Trial period</h3>\n              <p>{{ app.remaining_trial_period_days }} days remaining.</p>\n            </div>\n          {% endif %}\n\n        {% else  %}\n          <a href=\"{{ urls.applications }}\" class=\"btn btn-primary\">List My Application</a>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<div class=\"row\">\n  <div class=\"col-md-5\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <i class=\"fa fa-inbox\"></i>\n        Latest Messages\n        <a class=\"pull-right\" href=\"{{ urls.messages_inbox }}\" title=\"inbox\">\n          <i class=\"fa fa-chevron-right\"></i>\n        </a>\n\n      </div>\n      <div class=\"panel-body panel-footer\">\n        <ul class=\"list-unstyled\">\n          {% if current_account.latest_messages.size > 0 %}\n            {% for message in current_account.latest_messages %}\n              <li>{{ message.subject | link_to: message.url }}</li>\n            {% endfor %}\n          {% else %}\n            <li>No messages at this moment…</li>\n          {% endif %}\n        </ul>\n      </div>\n    </div>\n  </div>\n\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:45','2026-09-10 15:43:45',7,NULL,'',NULL,0,'dashboards/show'),(28,2,2,9,'CMS::Builtin::Page',NULL,'Reset password','password/new','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <i class=\"fa fa-coffee\"></i>\n        Forgot password\n      </div>\n      <div class=\"panel-body\">\n        {% form \'password_reset\', { class: \'form-horizontal\' } %}\n          <fieldset>\n            <div class=\"form-group\">\n              <label for=\"email\" class=\"control-label col-md-4\">Email address</label>\n              <div class=\"col-md-6\">\n                <input id=\"email\" name=\"email\" type=\"text\" class=\"form-control\" autofocus=\"autofocus\">\n                <span class=\"help-block\">Please enter the email address you used to sign up to this site. Instructions on how to reset your password will be sent to you.</span>\n              </div>\n            </div>\n          </fieldset>\n          <fieldset>\n            <div class=\"col-md-10\">\n              <input name=\"commit\" type=\"submit\" class=\"btn btn-success btn-lg pull-right\" value=\"Send instructions\">\n            </div>\n          </fieldset>\n        {% endform %}\n      </div>\n      <div class=\"panel-footer\">\n        <a href=\"{{ urls.login }}\" class=\"link\">\n          <i class=\"fa fa-chevron-left\"></i>\n          Sign in\n        </a>\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'password/new'),(29,2,2,9,'CMS::Builtin::Page',NULL,'Reset password form','password/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <i class=\"icon-coffee\"></i>\n        Change password\n      </div>\n      <div class=\"panel-body\">\n        {% form \'password_change\', password_reset_token, { class: \'form-horizontal\' } %}\n          <fieldset>\n            <div class=\"form-group\">\n              <label for=\"user_password\" class=\"control-label col-md-4\">Password</label>\n              <div class=\"col-md-6\">\n                <input id=\"user_password\" name=\"user[password]\" type=\"password\" class=\"form-control\" autofocus=\"autofocus\">\n                 {{ user.errors.password | inline_errors }}\n              </div>\n\n            </div>\n            <div class=\"form-group\">\n              <label for=\"user_password_confirmation\" class=\"control-label col-md-4\">Password confirmation</label>\n              <div class=\"col-md-6\">\n                <input id=\"user_password_confirmation\" name=\"user[password_confirmation]\" type=\"password\" class=\"form-control\">\n                 {{ user.errors.password_confirmation | inline_errors }}\n              </div>\n            </div>\n\n          </fieldset>\n          <fieldset>\n            <div class=\"col-md-10\">\n              <input name=\"commit\" type=\"submit\" class=\"btn btn-success btn-lg pull-right\" value=\"Change Password\">\n            </div>\n          </fieldset>\n        {% endform %}\n      </div>\n      <div class=\"panel-footer\">\n        <a href=\"{{ urls.login }}\" class=\"link\">\n          <i class=\"icon-chevron-left\"></i>\n          Sign in\n        </a>\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'password/show'),(30,2,2,10,'CMS::Builtin::Page',NULL,'Login','login/new','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <i class=\"fa fa-user\"></i>\n        Sign in\n      </div>\n      <div class=\"panel-body\">\n        {% include \'login/sso\' %}\n        {% form \'login\', user, class: \'form-horizontal\' %}\n          {% include \'login/cas\' with cas %}\n\n          <fieldset>\n            <div class=\"form-group\" id=\"session_username_input\">\n              <label for=\"session_username\" class=\"control-label col-md-4\">Username or Email</label>\n              <div class=\"col-md-6\">\n                <input id=\"session_username\" name=\"username\" tabindex=\"1\" autofocus=\"autofocus\"\n                       type=\"text\" placeholder=\"Authenticate with your email\"\n                       class=\"form-control\">\n              </div>\n            </div>\n            <div class=\"form-group\"  id=\"session_password_input\">\n              <label for=\"session_password\" class=\"control-label col-md-4\">Password</label>\n              <div class=\"col-md-6\">\n                <input id=\"session_password\" name=\"password\" tabindex=\"2\"\n                       type=\"password\" placeholder=\"…and password\"\n                       class=\"form-control\">\n              </div>\n            </div>\n\n            <input name=\"remember_me\" type=\"hidden\" value=\"1\">\n          </fieldset>\n          <fieldset>\n            <div class=\"form-group\">\n              <div class=\"col-md-10\">\n                <input name=\"commit\" type=\"submit\" value=\"Sign in\" class=\"btn btn-success btn-lg pull-right\">\n              </div>\n            </div>\n          </fieldset>\n        {% endform %}\n      </div>\n      <div class=\"panel-footer\">\n        <a href=\"{{ urls.forgot_password }}\">Forgot password?</a>\n\n        {% if provider.signups_enabled? %}\n          |  <a href=\"{{ urls.signup }}\" class=\"link\">Sign up</a>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'login/new'),(31,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'login/sso','{% unless user.oauth2? %}\n  <ul class=\"list-auth-provider row list-unstyled\">\n    {% for auth_provider in site.authentication_providers %}\n        <li class=\"col-md-offset-4 col-md-6\">\n      <a class=\"btn btn-default auth-provider auth-provider-{{auth_provider.kind}}\" href=\"{{auth_provider.authorize_url}}\">\n            <i class=\"fa fa-{{auth_provider.kind}}\"></i> Authenticate with {{ auth_provider.name }}\n          </a>\n        </li>\n    {% endfor %}\n  </ul>\n{% endunless %}\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,NULL,'',NULL,0,'login/_sso'),(32,2,2,11,'CMS::Builtin::Page',NULL,'Signup Form','signup/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <i class=\"fa fa-user\"></i>\n        Sign up\n      </div>\n      <div class=\"panel-body panel-footer\">\n\n        {% if plans.size > 0 %}\n        <div class=\"well well-sm\">\n          {% if plans.size > 1 %}\n            You are signing up with plans {{ plans | map: \'name\' | join:  \', \' }}.\n          {% else %}\n            You are signing up to plan {{ plans.first.name }}.\n          {% endif %}\n        </div>\n        {% endif %}\n\n        {% include \'signup/cas\' with cas %}\n        {% include \'login/sso\' %}\n        {% form \'signup\', account, class: \"form-horizontal\" %}\n\n          <fieldset>\n            {% if account.errors.plans == present %}\n              <div class=\"alert alert-danger\">{{ account.errors.plans | inline_errors: \'inline-errors\' }}</div>\n            {% endif %}\n\n            {% for field in account.fields %}\n              {% include \'field\' with field %}\n            {% endfor %}\n          </fieldset>\n\n          <fieldset>\n            {% for field in user.fields %}\n              {% include \'field\' with field %}\n            {% endfor %}\n          </fieldset>\n\n          {% if user.password_required? %}\n            <fieldset>\n              <div class=\"form-group {{ user.errors.password | error_class: \'has-error\' }}\">\n                <label for=\"account_user_password\" class=\"control-label col-md-4\">\n                  Password\n                  <abbr class=\"required\" title=\"required\">*</abbr>\n                </label>\n                <div class=\"col-md-6\">\n                  <input id=\"account_user_password\"\n                         name=\"account[user][password]\" type=\"password\"\n                         class=\"form-control\">\n                  {{ user.errors.password | inline_errors: \'inline-errors\' }}\n                </div>\n              </div>\n\n              <div class=\"form-group {{ user.errors.password_confirmation | error_class: \'has-error\' }}\">\n                <label for=\"account_user_password_confirmation\" class=\"control-label col-md-4\">\n                  Password confirmation\n                  <abbr class=\"required\" title=\"required\">*</abbr>\n                </label>\n                <div class=\"col-md-6\">\n                  <input id=\"account_user_password_confirmation\"\n                         name=\"account[user][password_confirmation]\"\n                         type=\"password\"\n                         class=\"form-control\" >\n                  {{ user.errors.password_confirmation | inline_errors: \'inline-errors\' }}\n                </div>\n              </div>\n            </fieldset>\n          {% endif %}\n\n\n          {% comment %}\n            The \'signup_licence\' partial is usually a place where a legal text\n            binding the developer on signup sits. It it does not exist\n            [default], the include is gracefully ignored.\n          {% endcomment %}\n\n\n          {% include \'signup_licence\' %}\n\n          <div class=\"form-group\">\n            <div class=\"col-md-10\">\n              <fieldset>\n                <input name=\"commit\" type=\"submit\" class=\"btn btn-success btn-lg pull-right\" value=\"Sign up\"/>\n              </fieldset>\n            </div>\n          </div>\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>\n{{ \'validate_signup.js\' | javascript_include_tag }}\n<script type=\"text/javascript\">\n  document.querySelector(\'input:not([type=\"hidden\"])\').focus()\n</script>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'signup/show'),(33,2,2,11,'CMS::Builtin::Page',NULL,'Signup Success','signup/success','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <i class=\"fa fa-user\"></i>\n        Sign up\n      </div>\n      <div class=\"panel-body panel-footer\">\n        <h2>Thank you</h2>\n        <p class=\"lead\">We have sent you an email to confirm your email address. Please click the link in the email and you can directly login!</p>\n        <p>(If you don\'t see the email, please check your spam box as well.)</p>\n      </div>\n    </div>\n  </div>\n</div>',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'signup/success'),(34,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'signup/cas','{% if cas %}\n  {% if cas.user_identified? %}\n    <div class=\"sso-signup auth\">\n      <p>Please continue the signup process below.</p>\n    </div>\n  {% else %}\n    <div class=\"sso-signup not-auth\">\n      <p>You can use your CAS account to login before signing up.</p>\n      {{ \"Login with CAS\" | link_to: cas.login_url }}\n    </div>\n  {% endif %}\n{% endif %}\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,NULL,'',NULL,0,'signup/_cas'),(35,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'messages/menu','<ul class=\"nav nav-tabs\">\n  <li class=\"{% if urls.messages_new.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_new }}\">Compose</a>\n  </li>\n  <li class=\"{% if urls.messages_inbox.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_inbox }}\">Inbox</a>\n  </li>\n  <li class=\"{% if urls.messages_outbox.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_outbox }}\">Sent Messages</a>\n  </li>\n  <li class=\"{% if urls.messages_trash.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_trash }}\">\n      <i class=\"fa fa-trash\"></i>\n      Trash\n    </a>\n  </li>\n</ul>\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,NULL,'',NULL,0,'messages/_menu'),(36,2,2,13,'CMS::Builtin::Page',NULL,'Outbox','messages/outbox/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'messages/menu\'%}\n    <table class=\"table panel panel-default\" id=\"messages\">\n      <thead class=\"panel-heading\">\n        <tr>\n          <th>Subject</th>\n          <th>To</th>\n          <th colspan=\"2\">Date sent</th>\n        </tr>\n      </thead>\n      <tbody class=\"panel-body panel-footer\">\n        {% if messages.size > 0 %}\n          {% for message in messages %}\n            <tr class=\"{{ message.state }}\">\n              <td><a href=\"{{ message.url }}\">{{ message.subject }}</a></td>\n              <td>{{ message.recipients }}</td>\n              <td>{{ message.created_at }}</td>\n              <td>{{ \'<i class=\"fa fa-trash\"></i>\' | html_safe | link_to: message.url, title: \'Delete message\', method: \'delete\' }}</td>\n            </tr>\n          {% endfor %}\n        {% else %}\n          <tr>\n            <td colspan=\"4\">Your outbox is empty.</td>\n          </tr>\n        {% endif %}\n      </tbody>\n    </table>\n  </div>\n</div>\n{% include \'shared/pagination\' with pagination %}\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'messages/outbox/index'),(37,2,2,13,'CMS::Builtin::Page',NULL,'View Message','messages/outbox/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'messages/menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <a href=\"{{ urls.messages_outbox }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          All messages\n        </a>\n        <span class=\"pull-right\">\n          {{ \'<i class=\"fa fa-trash\"></i>\' | html_safe | link_to: message.url, method: \'delete\' }}\n        </span>\n      </div>\n      <div class=\"panel-body panel-footer\">\n        <dl class=\"dl-horizontal\">\n          <dt>Subject</dt>\n          <dd>{{ message.subject }}</dd>\n          <dt>Sent</dt>\n          <dd>by {{ message.sender }} at {{ message.created_at | date: i18n.long_date }}</dd>\n          <dt>Message</dt>\n          <dd><pre class=\"message\">{{ message.body }}</pre></dd>\n        </dl>\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'messages/outbox/show'),(38,2,2,13,'CMS::Builtin::Page',NULL,'Compose','messages/outbox/new','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'messages/menu\'%}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n      </div>\n      <div class=\"panel-body panel-footer\">\n        {% form \'message.create\', message, { class: \'form-horizontal\' } %}\n          <fieldset>\n          <div class=\"form-group\">\n            <label class=\"col-md-3 control-label\">To</label>\n            <div class=\"col-md-6\">\n              <p class=\"form-control-static\">{{ message.to }}</p>\n            </div>\n          </div>\n          <div class=\"form-group\">\n            <label class=\"col-md-3 control-label\" for=\"message_subject\">Subject</label>\n            <div class=\"col-md-6\">\n              <input tabindex=\"1\"\n                  autofocus=\"autofocus\"\n                  id=\"message_subject\" name=\"message[subject]\" type=\"text\" class=\"form-control\">\n            </div>\n          </div>\n\n          <div class=\"form-group\">\n            <label for=\"message_body\" class=\"col-md-3 control-label\">Body</label>\n            <div class=\"col-md-7\">\n              <textarea id=\"message_body\"\n                        name=\"message[body]\"\n                        rows=\"10\"\n                        class=\"form-control\"\n                        tabindex=\"1\"></textarea>\n            </div>\n          </div>\n\n         <div class=\"form-group\">\n            <div class=\"col-md-10\">\n              <button type=\"submit\" class=\"btn btn-primary pull-right\" tabindex=\"3\">Send</button>\n            </div>\n          </div>\n        </fieldset>\n        <!--\n          <fieldset class=\"inputs\">\n            <ol>\n              <li>\n                <label>To:</label>\n                <input id=\"to\" name=\"to\" readonly=\"readonly\" type=\"text\" value=\"{{ message.to }}\">\n              </li>\n              <li class=\"string optional\" id=\"message_subject_input\">\n                <label for=\"message_subject\">\n                  Subject\n                </label>\n               <input id=\"message_subject\" name=\"message[subject]\" type=\"text\">\n              </li>\n              <li class=\"text optional\" id=\"message_body_input\">\n                <label for=\"message_body\">\n                  Body\n                </label>\n                <textarea id=\"message_body\" name=\"message[body]\" rows=\"10\"></textarea>\n              </li>\n              <fieldset class=\"buttons\">\n                <ol>\n                  {% if request.xhr? %}\n                    <li class=\"link\">\n                      {{ \"Cancel\" | link_to: urls.messages_inbox, class: \'fancybox-close\' }}\n                    </li>\n                  {% endif %}\n                  <li class=\"commit\">\n                    <input class=\"important-button create\" name=\"commit\" type=\"submit\" value=\"Send\">\n                  </li>\n                </ol>\n              </fieldset>\n            </ol>\n          </fieldset>\n        -->\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'messages/outbox/new'),(39,2,2,14,'CMS::Builtin::Page',NULL,'Inbox','messages/inbox/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'messages/menu\' %}\n    <table class=\"table panel panel-default\">\n      <thead class=\"panel-heading\">\n        <tr>\n          <th>Subject</th>\n          <th>From</th>\n          <th colspan=\"2\">Received</th>\n        </tr>\n      </thead>\n      <tbody class=\"panel-body panel-footer\">\n        {% if messages.size > 0 %}\n          {% for message in messages %}\n            <tr class=\"{{ message.state }}\">\n              <td>{{ message.subject | link_to: message.url }}</td>\n              <td>{% if message.sender == present %}{{ message.sender }}{% else %}<span class=\"deleted\">(user deleted)</span>{% endif %}</td>\n              <td>{{ message.created_at }}</td>\n              <td>{{ \'<i class=\"fa fa-trash\"></i>\' | html_safe | link_to: message.url, title: \'Delete message\', method: \'delete\' }}</td>\n            </tr>\n          {% endfor %}\n        {% else %}\n          <tr>\n            <td colspan=\"4\">Your inbox is empty.</td>\n          </tr>\n        {% endif %}\n      </tbody>\n    </table>\n  </div>\n</div>\n{% include \'shared/pagination\' with pagination %}\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'messages/inbox/index'),(40,2,2,14,'CMS::Builtin::Page',NULL,'View Message','messages/inbox/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'messages/menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        <a href=\"{{ urls.messages_inbox }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          All messages\n        </a>\n        <span class=\"pull-right\">\n          {{ \'<i class=\"fa fa-trash\"></i>\' | html_safe | link_to: message.url, method: \'delete\' }}\n        </span>\n      </div>\n      <div class=\"panel-body\">\n        <dl class=\"dl-horizontal\">\n          <dt>Subject</dt>\n          <dd>{{ message.subject }}</dd>\n          <dt>Received</dt>\n          <dd>from {{ message.sender }} at {{ message.created_at | date: i18n.long_date }}</dd>\n          <dt>Message</dt>\n          <dd><pre class=\"message\">{{ message.body }}</pre></dd>\n        </dl>\n      </div>\n\n      <div class=\"panel-footer important\">\n        {% comment %} only embed reply form if there is a sender to reply to {% endcomment %}\n        {% if reply %}\n          {% form \'message.reply\', reply, { class: \'form-horizontal\' } %}\n            <div class=\"form-group\">\n              <input id=\"reply_to\" name=\"reply_to\" type=\"hidden\" value=\"{{ message.id }}\">\n              <input type=\"hidden\" name=\"message_subject\" value=\"Re: {{message.subject}}\">\n              <label class=\"col-md-3 control-label\" for=\"message_body\">Reply</label>\n              <div class=\"col-md-7\">\n                <textarea id=\"message_body\"\n                          name=\"message[body]\"\n                          rows=\"10\"\n                          class=\"form-control\"\n                          tabindex=\"1\"></textarea>\n              </div>\n            </div>\n            <div class=\"form-group\">\n              <div class=\"col-md-10\">\n                <button type=\"submit\" class=\"btn btn-primary pull-right\" tabindex=\"3\">Send reply</button>\n              </div>\n            </div>\n          {% endform %}\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'messages/inbox/show'),(41,2,2,15,'CMS::Builtin::Page',NULL,'Trash','messages/trash/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'messages/menu\'%}\n    <table class=\"table panel panel-default\" id=\"messages\">\n      <thead class=\"panel-heading\">\n        <tr>\n          <th>Subject</th>\n          <th>From</th>\n          <th colspan=\"2\">Date sent</th>\n        </tr>\n      </thead>\n      <tbody class=\"panel-body\">\n        {% if messages.size > 0  %}\n          {% for message in messages %}\n            <tr class=\"{% cycle \'messages\': \'odd\', \'even\' %}\">\n              <td>{{ message.subject | link_to: message.url }}</td>\n              <td>{{ message.sender | link_to: message.url }}</td>\n              <td>{{ message.created_at }}</td>\n              <td>{{ \'Restore\' | delete_button: message.url, class: \'btn btn-default\' }}</td>\n            </tr>\n          {% endfor %}\n        {% else %}\n          <tr>\n            <td class=\"empty\" colspan=\"4\">Your trash is empty.</td>\n          </tr>\n        {% endif %}\n      </tbody>\n      <tfoot class=\"panel-footer\">\n        <tr>\n          <td colspan=\"4\">\n            {% if messages.size > 0  %}\n              {{ \"Delete received messages\" | delete_button: urls.empty_messages_trash, class: \'btn btn-danger\' }}\n            {% endif %}\n          </td>\n        </tr>\n      </tfoot>\n    </table>\n  </div>\n</div>\n{% include \'shared/pagination\' with pagination %}\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'messages/trash/index'),(42,2,2,15,'CMS::Builtin::Page',NULL,'View Message','messages/trash/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'messages/menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        {{ message.subject }} <span class=\"pull-right\">by {{ message.sender }} at {{ message.created_at | date: i18n.long_date }}</span>\n      </div>\n      <div class=\"panel-body panel-footer\">\n        <pre class=\"message\">{{ message.body }}</pre>\n      </div>\n    </div>\n  </div>\n</div>',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'messages/trash/show'),(43,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'stats/chart','{% content_for stylesheets %}\n  {{ \'stats.css\' | stylesheet_link_tag }}\n  {% cdn_asset /jquery-ui/1.11.4/jquery-ui.css %}\n{% endcontent_for %}\n\n{% content_for javascripts %}\n    {{ \'stats.js\' | javascript_include_tag }}\n{% endcontent_for %}\n\n<div class=\"panel panel-default\">\n  <div class=\"panel-heading\">\n    <i class=\"fa fa-bar-chart\"></i>\n    Graphs\n  {% if provider.multiple_applications_allowed? %}\n      <div id=\"applications-selector-container\" class=\"StatsApplicationsSelectorContainer\">\n          <select id=\"application-select\" name=\"application\">\n              {% assign groups = applications | group_by: \'service\' %}\n              {% for group in groups %}\n                  <optgroup label=\"{{group[0].name}}\">\n                      {% for application in group[1] %}\n                          <option value=\"{{application.id}}\">{{ application.name }}</option>\n                      {% endfor %}\n                  </optgroup>\n              {% endfor %}\n          </select>\n      </div>\n  {% endif %}\n  </div>\n  <div class=\"panel-body\">\n    <div class=\"StatsMenuContainer\" id=\"menu-container\"></div>\n    <div class=\"StatsSelectorContainer\" id=\"selector-container\"></div>\n    <div class=\"StatsChartContainer\" id=\"chart-container\"></div>\n    <p id=\"timezone-info\" data-timezone-identifier=\"{{provider.timezone.identifier}}\" class=\"Stats-message--notice\">\n        Using time zone {{ provider.timezone.full_name }}\n    </p>\n    <div class=\"StatsMethodsTableContainer\" id=\"methods-table-container\"></div>\n  </div>\n  <div class=\"panel-footer\">\n    <div class=\"CsvLinkContainer\" id=\"csv-link-container\"></div>\n  </div>\n</div>\n\n<script type=\"text/javascript\" charset=\"utf-8\">\n  (function() {\n    var applicationGroups = {};\n\n    {% if provider.multiple_applications_allowed? %}\n      /*\n        Gets the service name and application names and ids from the liquid rendered selector\n        Returns an object with the service name as a key, and an array of applications\n        I.E: {\'Echo API\': [{id: 42, name: \'The Answer\'}]}\n       */\n      function applicationGroupsFromSelector () {\n        $(\'.StatsApplicationsSelectorContainer select optgroup\').each(function (_i, group) {\n          let applications = applicationGroups[$(group).attr(\'label\')] = [];\n          $(group).children().each(function (_j, application) {\n            applications.push({id: $(application).val(), name: $(application).html()})\n          })\n        })\n        return applicationGroups;\n      }\n      applicationGroups = applicationGroupsFromSelector()\n    {% endif %}\n\n    Stats.statsApplication(jQuery(\'#client-name\').attr(\'data-client\'),\n      {\n        menuContainer: \'#menu-container\',\n        selectorContainer: \'#selector-container\',\n        chartContainer: \'#chart-container\',\n        methodsTableContainer: \'#methods-table-container\',\n        csvLinkContainer: \'#csv-link-container\',\n        timezone: $(\'#timezone-info\').data(\'timezone-identifier\'),\n        hasApplicationsSelector: Object.keys(applicationGroups).length > 0,\n        applicationGroups: applicationGroups,\n        applicationsSelectorContainer: \'#applications-selector-container\'\n      }\n    );\n\n    })();\n</script>\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,NULL,'',NULL,0,'stats/_chart'),(44,2,2,16,'CMS::Builtin::Page',NULL,'Stats','stats/index','<div class=\"row\">\n  {% if provider.multiple_applications_allowed? %}\n    {% if applications == present %}\n      <div id=\"client-name\" data-client=\"{{ applications.first.id }}\" style=\"display:none\"></div>\n      {% include \'stats/chart\' %}\n    {% else %}\n      <p>You do not currently have any live applications.</p>\n    {% endif %}\n  {% else %}\n    <div id=\"client-name\" data-client=\"{{ applications.first.id }}\" style=\"display:none\"></div>\n    {% include \'stats/chart\' %}\n  {% endif %}\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'stats/index'),(45,2,2,NULL,'CMS::Builtin::Partial',NULL,NULL,'applications/form','<input type=\"hidden\" id=\"cinstance_plan_id\" name=\"application[plan_id]\" value=\"{{ application.plan.id }}\" />\n\n<fieldset>\n  <div class=\"form-group\" id=\"selected-plan\" data-plan-id=\"{{ application.plan.id }}\">\n    <label class=\"control-label col-md-4\">Plan</label>\n    <div class=\"col-md-6\">\n\n        <p class=\"form-control-static\">\n          <strong id=\'selected-plan-name\'>{{application.plan.name}}</strong>\n          {% if application.can_change_plan? %}\n            <span>› </span>\n            <a href=\"#choose-plan-{{ application.id }}\" id=\"choose-plan-{{application.id}}\">\n              Review/Change\n            </a>\n            {% plan_widget application, wizard: true %}\n            {{ \'/css/plans_widget_overrides.css\' | stylesheet_link_tag }}\n          {% endif %}\n        </p>\n\n    </div>\n  </div>\n</fieldset>\n\n<fieldset>\n  {% for field in application.fields %}\n    {% include \'field\' with field %}\n  {% endfor %}\n</fieldset>\n\n{% include \'new_application_licence\' %}\n\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,NULL,'',NULL,0,'applications/_form'),(46,2,2,4,'CMS::Builtin::Page',NULL,'Edit Application','applications/edit','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <a href=\"{{ application.url }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          {{ application.name }}\n        </a>\n        {% if application.can.be_destroyed? %}\n          <a href=\"{{ application.path }}\" class=\"pull-right\" data-method=\"delete\" data-confirm=\"Are you sure you want to delete the application {{ application.name }} ?\">\n            <i class=\"fa fa-trash-o\"></i>\n            Delete {{ application.name }}\n          </a>\n        {% endif %}\n      </div>\n      <div class=\"panel-body panel-footer\">\n        {% form \'application.update\', application, class: \"form-horizontal\" %}\n          {% include \'applications/form\' %}\n          <fieldset>\n            <div class=\"form-group\">\n              <div class=\"col-md-10\">\n                <input class=\"btn btn-primary pull-right\"\n                  name=\"commit\"\n                  type=\"submit\"\n                  value=\"Update Application\" />\n              </div>\n            </div>\n          </fieldset>\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'applications/edit'),(47,2,2,4,'CMS::Builtin::Page',NULL,'Application','applications/show','{% disable_client_cache %}\n\n<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n\n        {% capture state_label %}\n          {% case application.state %}\n            {% when \'pending\' %}   label-default\n            {% when \'live\' %}      label-success\n            {% when \'suspended\' %} label-warning\n          {% endcase %}\n        {% endcapture %}\n\n        <a href=\"{{ urls.applications }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          Applications\n        </a>\n\n        {% if application.can.be_updated? %}\n          <a href=\"{{ application.edit_url }}\" class=\"pull-right\">\n            <i class=\"fa fa-pencil\"></i>\n            Edit {{ application.name }}\n          </a>\n        {% endif %}\n      </div>\n      <div class=\"panel-body body-footer\">\n        <dl class=\"dl-horizontal\">\n          <dt>Name</dt>\n          <dd>{{ application.name }}</dd>\n          <dt>Description</dt>\n          <dd>{{ application.description }}</dd>\n          <dt> Plan </dt>\n          <dd>\n            <strong>{{application.plan.name}}</strong>\n            {% if application.can_change_plan? %}\n              <span>› </span>\n              <a href=\"#choose-plan-{{ application.id }}\" id=\"choose-plan-{{application.id}}\">\n                Review/Change\n              </a>\n              {% plan_widget application, wizard: true %}\n              {{ \'/css/plans_widget_overrides.css\' | stylesheet_link_tag }}\n            {% endif %}\n          </dd>\n        </dl>\n        <hr/>\n        <dl class=\"dl-horizontal\">\n          <dt>Status</dt>\n          <dd><span class=\"label {{ state_label | strip_newlines }}\">&nbsp;</span> {{ application.state | capitalize}}\n            {% if application.pending? %}\n              <p class=\"alert alert-warning\">Your application is awaiting approval. This can take a little time - you will be notified by email.</p>\n            {% endif %}\n          </dd>\n          {% if application.buyer_alerts_enabled? %}\n            <dd>\n              <a href=\"{{ application.alerts_url }}\" class=\"action\">{{ application.alerts.size }} usage alert(s)</a>\n            </dd>\n          {% endif %}\n        </dl>\n        <hr/>\n        <dl class=\"dl-horizontal\">\n          {% if application.user_key_mode? %}\n            <dt>User Key</dt>\n            <dd><code id=\"user-key\">{{ application.user_key }}</code>\n              <p class=\"help-block\"> Add this as a <code>user_key</code>\n                parameter to your API calls to report and\n                authenticate.</p>\n                              {% if application.can.regenerate_user_key? %}\n                   {{ \'Regenerate\' | update_button: application.update_user_key_url, class: \'btn btn-danger btn-xs\' }}\n              {% endif %}\n            </dd>\n          {% elsif application.oauth_mode? %}\n          <div class=\'data-container\' data-backend=\"oauth\">\n            <dt>Client ID</dt>\n            <dd class=\"key\">\n              <code>{{ application.application_id }}</code>\n              <p class=\'sub\'>This is the Client ID you should send with each API request.</p>\n            </dd>\n          </div>\n          <div class=\"data-container\" id=\"application_keys\">\n            <dt>Client Secret</dt>\n            <dd class=\"key\">\n              <code>{{ application.keys.first }}</code>\n              <p class=\'sub\'>This the Client Secret used to authenticate requests.</p>\n              <p>\n                {% if application.keys.size == 0 %}\n                {{ \'Create secret\' | create_button: application.oauth.create_secret_url }}\n                {% elsif application.can.regenerate_oauth_secret? %}\n                {{ \'Regenerate\' | regenerate_oauth_secret_button: application.oauth.regenerate_secret_url }}\n                {% endif %}\n              </p>\n            </dd>\n          </div>\n          <div class=\'data-container\' id=\"redirect_url\">\n            <dt>Redirect URL</dt>\n            <dd class=\"key\">\n              <p class=\'sub\'>This is your Redirect URL for OAuth.</p>\n              {% form \'application.updateremote\', application %}\n              <fieldset class=\"inputs\">\n                <label for=\"application_redirect_url\">Redirect URL</label>\n                <input type=\"text\" id=\"application_redirect_url\"\n                name=\"application[redirect_url]\"\n                value=\"{{ application.redirect_url }}\"\n                class=\"{{ application.errors.redirect_url | error_class }}\"/>\n                {{ application.errors.redirect_url | inline_errors }}\n              </fieldset>\n\n              <fieldset class=\"buttons\">\n                <input class=\"btn btn-success\" name=\"commit\" type=\"submit\" value=\"Submit\">\n              </fieldset>\n              {% endform %}\n            </dd>\n          </div>\n          {% else %}\n            <div class=\'data-container\' data-backend=\"app_id\">\n              <dt>Application ID</dt>\n              <dd class=\"key\">\n                <code>{{ application.application_id }}</code>\n                <p class=\'sub\'>This is the application ID, you should send with each API request.</p>\n              </dd>\n            </div>\n\n            {% if application.can.manage_keys? %}\n                <dt>Application Keys</dt>\n                <dd>\n                  <div class=\'data-container\' id=\"application_keys\">\n                    <table class=\"table\" id=\"keys\">\n                      {% for key in application.application_keys %}\n                        <tr id=\"application_key_{{key.value}}\" data-key=\"{{key.value}}\">\n                          <td class=\"key\"><code>{{ key.value }}</code></td>\n                          <td class=\"delete_key\">\n                            {% if application.can.delete_key? %}\n                              {{ \'Delete\' | delete_button_ajax: key.url, class: \'btn btn-danger btn-xs\' }}\n                            {% else %}\n                              &mdash;\n                            {% endif %}\n                          </td>\n                        </tr>\n                      {% endfor %}\n                    </table>\n                    <p class=\'sub\'>These are application keys used to authenticate requests.</p>\n                    <div class=\"operations\">\n                      {% if application.can.add_application_keys? %}\n                        <div class=\"enabled_block\">\n                          {{ \'Create new key\' | create_button_ajax: application.application_keys_url, class: \'btn btn-success btn-xs\' }}\n                        </div>\n                      {% else %}\n                        <div class=\"disabled_block\">\n                          <p class=\"mini_info\">At most {{ application.keys_limit }} keys are allowed.</p>\n                        </div>\n                      {% endif %}\n                    </div>\n                  </div>\n                </dd>\n              {% endif %} <!-- /if application can manage keys? -->\n            {% endif %}\n\n          {% for field in application.extra_fields %}\n            {% if field.value != \"\" %}\n              {% if field.visible? %}\n                <dt>{{ field.label }}</dt>\n                <dd>{{ field.value }}</dd>\n              {% endif %}\n            {% endif %}\n          {% endfor %}\n        </dl>\n\n        {% if application.service.referrer_filters_required? %}\n          <dl class=\"dl-horizontal\" id=\"referrer_filters\">\n            <dt>Referrer Filters</dt>\n            <dd>If you are developing a server based application you typically need to add IP addresses, if it is widget based you typically need to add domain names. Specify allowed referrer domains or IP addresses. Wildcards (*.example.org) are also accepted.</dd>\n            <dd>\n              <div class=\"enabled_block\">\n                {% form \'referrer_filter.createremote\', referrer_filter %}\n                  <input type=\"text\" id=\"referrer_filter\" name=\"referrer_filter\" />\n                  <input type=\"submit\" value=\"Add\" name=\"commit\" />\n                {% endform %}\n              </div>\n              <div class=\"disabled_block\">At most {{ application.filters_limit }} referrer filters are allowed.</div>\n            </dd>\n            <dd>\n              <table class=\"table\">\n                {% for filter in application.referrer_filters %}\n                  <tr class=\"{% cycle \'applications\': \'odd\', \'even\' %}\" id=\"referrer_filter_{{ filter.id }}\">\n                    <td>{{ filter.value }}</td>\n                    <td>{{ \"Delete\" | delete_button_ajax: filter.delete_url }}</td>\n                  </tr>\n                {% endfor %}\n              </table>\n            </dd>\n          </dl>\n          {% if application.can.add_referrer_filters? %}\n            <script type=\"text/javascript\">\n              $(function() {\n                $(\"div#referrer_filters\").enableSwitch();\n              });\n            </script>\n          {% else %}\n            <script type=\"text/javascript\">\n              $(function() {\n                $(\"div#referrer_filters\").disableSwitch();\n              });\n            </script>\n          {% endif %}\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'applications/show'),(48,2,2,4,'CMS::Builtin::Page',NULL,'List Applications','applications/index','{% disable_client_cache %}\n\n<div class=\"row\">\n  <div class=\"col-md-9\">\n    <table class=\"table panel panel-default\" id=\"applications\">\n      <thead class=\"panel-heading\">\n        <tr>\n          <th>Name</th>\n          {% if provider.services.size > 1 %}\n            <th>Service</th>\n          {% endif %}\n          <th>Credentials</th>\n          <th>State</th>\n          <th>\n          </th>\n        </tr>\n      </thead>\n      <tbody class=\"panel-body\">\n        {% for application in applications %}\n          <tr class=\"{% cycle \'applications\': \'odd\', \'even\' %}\" id=\"application_{{ application.id }}\">\n            <td>\n              {{ application.name | link_to: application.url }}\n            </td>\n            {% if provider.services.size > 1 %}\n              <td>{{ application.service.name }}</td>\n            {% endif %}\n            <td>{{ application.key }}</td>\n            <td>{{ application.state }}</td>\n            <td>\n              {% if application.can.be_updated? %}\n                <a href=\"{{ application.edit_url }}\">\n                  <i class=\"fa fa-pencil\"></i>\n                </a>\n              {% endif %}\n            </td>\n          </tr>\n        {% endfor %}\n      </tbody>\n      <tfoot class=\"panel-footer\">\n      <tr>\n        <td colspan=\"{% if provider.services.size > 1 %}4{% else %}3{% endif %}\">\n        </td>\n        <td>\n          {% if current_user.can.create_application? %}\n            <a href=\"{{ urls.new_application }}\" title=\"Create new application\" class=\"btn btn-primary\">Create new application</a>\n          {% endif %}\n        </td>\n      </tr>\n      </tfoot>\n    </table>\n\n    {% include \'shared/pagination\' with pagination %}\n\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'applications/index'),(49,2,2,17,'CMS::Builtin::Page',NULL,'List Alerts','applications/alerts/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <a href=\"{{ application.url }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          Application {{ application.name }}\n        </a>\n      </div>\n      <div class=\"panel-heading\">\n        <h3 class=\"panel-title\">Alerts</h3>\n      </div>\n      <table class=\"table panel panel-default\" id=\"limit_alerts\">\n        <thead class=\"panel-heading\">\n          <tr>\n            <th>Message</th>\n            <th>{% sort_link column: \"level\" %}</th>\n            <th>{% sort_link column: \"timestamp\" label: \"Time\" %}</th>\n            <th>\n              {% if alerts.size > 0 %}\n                {{ \'Delete all\' | delete_button: application.purge_alerts_url, class: \'delete btn btn-default btn-sm\', confirm: \'Do you really want to delete all alerts? There is no undo.\' }}\n              {% endif %}\n            </th>\n          </tr>\n        </thead>\n        <tbody class=\"panel-body panel-footer\">\n          {% if alerts.size > 0 %}\n            {% for alert in alerts %}\n              <tr class=\"alert\" id=\"alert\">\n                <td>{{ alert.message }}</td>\n                <td>{{ alert.formatted_level }}</td>\n                <td>{{ alert.timestamp | date: i18n.default_time }}</td>\n                <td>\n                  {{ \'<i class=\"fa fa-trash\"></i>\' | html_safe | link_to:  alert.delete_alert_url, title: \'Delete alert\', method: \'delete\' }}\n                </td>\n              </tr>\n            {% endfor %}\n          {% else %}\n            <tr class=\"no_results\">\n              <td colspan=\"5\">There are no recent alerts or violations.</td>\n            </tr>\n          {% endif %}\n        </tbody>\n      </table>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'applications/alerts/index'),(50,2,2,18,'CMS::Builtin::Page',NULL,'Invoices list','invoices/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <table class=\"panel panel-default table\">\n      <thead class=\"panel-heading\">\n        <tr>\n          <th>ID</th>\n          <th>Month</th>\n          <th>State</th>\n          <th>Amount</th>\n          <th colspan=\'2\'></th>\n        </tr>\n      </thead>\n      <tbody class=\"panel-body panel-footer \">\n        {% for invoice in invoices %}\n          <tr class=\"invoice {% cycle \'odd\', \'even\' %}\">\n            <td> {{ invoice.friendly_id }} </td>\n            <td> {{ invoice.name }} </td>\n            <td> {{ invoice.state }} </td>\n            <td> {{ invoice.currency }} {{ invoice.cost }} </td>\n            <td>\n              {% assign title = \'Show \' | append: invoice.friendly_id %}\n              {{ \'Show\' | link_to: invoice.url, title: title, class: \'btn btn-default\'  }}\n            </td>\n            <td>\n              {% if invoice.exists_pdf? %}\n                {{ \'PDF\' | link_to: invoice.pdf_url, title: \'Show pdf\' }}\n              {% endif %}\n            </td>\n          </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n    {% include \'shared/pagination\' with pagination %}\n    <h3>Support</h3>\n    <p>Contact us by email: {{ provider.finance_support_email }}</p>\n  </div>\n</div>\n\n\n\n\n\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'invoices/index'),(51,2,2,18,'CMS::Builtin::Page',NULL,'Invoice details','invoices/show','<style type=\"text/css\" media=\"screen\">\ntable#line-items {\n  margin-top: 1em;\n  margin-bottom: 1em;\n}\n</style>\n\n\n<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        <div class=\"clearfix\">\n          <a href=\"{{ urls.invoices }}\">\n            <i class=\"fa fa-chevron-left\"></i>\n            Cancel\n          </a>\n          {{ invoice.period_begin | date: \'%B, %Y\' }} Invoice\n          {% if invoice.pay_now? %}\n            <a href=\"{{invoice.url}}/payment\" class=\"pull-right btn btn-success pay-invoice-btn\">Pay invoice</a>\n          {% endif %}\n        </div> \n      </div>\n      <div class=\"panel-body panel-footer\">\n\n        <dl class=\"dl-horizontal\">\n          <dt>ID</dt>\n          <dd>{{ invoice.friendly_id }}</dd>\n          <dt>State</dt>\n          <dd>{{ invoice.state | capitalize }}</dd>\n          <dt>Billing period</dt>\n          <dd>{{ invoice.period_begin | date: i18n.long_date }} - {{ invoice.period_end | date: i18n.long_date }}</dd>\n          <dt>Issued on</dt>\n          <dd>{{ invoice.issued_on | date: i18n.long_date }}</dd>\n          <dt>Due on</dt>\n          <dd>{{ invoice.due_on | date: i18n.long_date }}</dd>\n          <dt>Paid on</dt>\n          <dd>{{ invoice.paid_on | date: i18n.long_date }}</dd>\n          {% if invoice.exists_pdf? %}\n          <dt>PDF</dt>\n          <dd>{{ \'Download PDF\' | link_to: invoice.pdf_url, title: \'Show pdf\', class: \'link\' }}</dd>\n          {% endif %}\n        </dl>\n\n\n        <div class=\"row\">\n          <div class=\"col-lg-6\">\n            <h3>Issued by (API provider)</h3>\n            <dl class=\"dl-horizontal\">\n              <dt>Name</dt>\n              <dd>{{ provider.name }}</dd>\n              <dt>Country</dt>\n              <dd>{{ provider.country_name }}</dd>\n              <dt>Address</dt>\n              <dd>{{ provider.full_address }}</dd>\n            </dl>\n          </div>\n\n          {% assign developer = invoice.account %}\n          <div class=\"col-lg-6\">\n            <h3>For (developer)</h3>\n            <dl class=\"dl-horizontal\">\n              <dt>Name</dt>\n              <dd>{{ developer.name }}</dd>\n              <dt>Address</dt>\n              <dd>{{ developer.full_address }}</dd>\n              <dt>Country</dt>\n              <dd>{{ developer.country_name }}</dd>\n              {% if invoice.vat_code == present %}\n                <dt>VAT Code</dt>\n                <dd>{{ invoice.vat_code }}</dd>\n              {% endif %}\n              {% if invoice.fiscal_code == present %}\n                <dt>Fiscal Code</dt>\n                <dd>{{ invoice.fiscal_code }}</dd>\n              {% endif %}\n            </dl>\n          </div>\n        </div>\n\n        <table id=\"line_items\" class=\"table table-striped table-bordered\">\n          <thead>\n            <tr>\n              <th> Name </th>\n              <th> Description </th>\n              <th> Quantity </th>\n              <th> Price </th>\n            </tr>\n          </thead>\n          <tbody>\n            {% for line_item in invoice.line_items %}\n              <tr class=\"line_item {% cycle \'odd\', \'even\' %}\">\n                <th>{{ line_item.name }}</th>\n                <td>{{ line_item.description }}</td>\n                <td>{{ line_item.quantity }}</td>\n                <td>{{ invoice.currency }} {{ line_item.cost }}</td>\n              </tr>\n            {% endfor %}\n          </tbody>\n\n          <tfoot>\n            {% if invoice.vat_rate == nil %}\n              <tr>\n                <th> Total cost</th>\n                <td></td>\n                <td></td>\n                <td id=\"invoice_cost\">\n                  {{ invoice.currency }} {{ invoice.cost }}\n                </td>\n              </tr>\n            {% else %}\n              <tr>\n                <th> Total cost (whithout VAT) </th>\n                <td></td>\n                <td></td>\n                <td id=\"invoice_cost_without_vat\">\n                  {{ invoice.currency }} {{ invoice.cost_without_vat }}\n                </td>\n              </tr>\n              <tr>\n                <th> VAT Amount </th>\n                <td></td>\n                <td></td>\n                <td id=\"invoice_cost_vat_amount\">\n                 {{ invoice.currency }} {{ invoice.vat_amount }}\n                </td>\n              </tr>\n              <tr>\n                <th> Total cost (VAT {{ invoice.vat_rate }}% included) </th>\n                <td></td>\n                <td></td>\n                <td id=\"invoice_cost\">\n                  {{ invoice.currency }} {{ invoice.cost }}\n                </td>\n              </tr>\n            {% endif %}\n          </tfoot>\n        </table>\n\n        {% if invoice.vat_rate == 0 %}\n          <p id=\"vat-zero-text\">\n            {{ provider.vat_zero_text }}\n          </p>\n        {% endif %}\n\n        {% if invoice.payment_transactions.size > 0 %}\n          <table id=\"payment_transactions\" class=\"table table-striped table-bordered\" >\n            <caption>Transactions</caption>\n            <thead>\n              <tr>\n                <th></th>\n                <th>Status</th>\n                <th>Created At</th>\n                <th>Reference</th>\n                <th>Message</th>\n                <th>Amount</th>\n              </tr>\n            </thead>\n\n            <tbody>\n            {% for payment_transaction in invoice.payment_transactions %}\n              <tr class=\"{% if payment_transaction.success? %}success{% else %}danger{% endif %}\">\n                <td>\n                  {% if payment_transaction.success? %} {{ \'tick.png\' | image_tag }} {% else %} {{ \'cross.png\' | image_tag }} {% endif %}\n                </td>\n                <td>\n                  {% if payment_transaction.success? %} Success {% else %} Failure {% endif %}\n                </td>\n                <td>\n                  {{ payment_transaction.created_at }}\n                </td>\n                <td>\n                  {{ payment_transaction.reference }}\n                </td>\n                <td>\n                  {{ payment_transaction.message }}\n                </td>\n                <td>\n                  {{ payment_transaction.amount }}\n                  {{ payment_transaction.currency }}\n                </td>\n              </tr>\n            {% endfor %}\n            </tbody>\n          </table>\n        {% else %}\n          <p class=\"help-block\">No transactions registered for this invoice.</p>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'invoices/show'),(52,2,2,19,'CMS::Builtin::Page',NULL,'Change Plan','account_plans/index','\n<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n      </div>\n      <div class=\"panel-body panel-footer\">\n        {% assign contract = current_account.bought_account_contract %}\n        {% if contract.can_change_plan? %}\n          <p>You are currently on plan <em>{{ contract.plan.name | capitalize }}</em>.</p>\n          {% form \'plan.change\' %}\n            <p>\n              <label for=\"plan-select\" style=\"display:inline\">View plan</label>:\n              <select id=\"plan-select\" name=\"plan_id\">\n                {% for account_plan in account_plans %}\n                  <option value=\"{{ account_plan.id }}\">{{ account_plan.name }}</option>\n                {% endfor %}\n              </select>\n              <input data-confirm=\"{{ contract.plan_change_permission_warning }}\" id=\"plan-change-submit\" name=\"commit\" style=\"display:none;\" type=\"submit\" value=\"{{ contract.plan_change_permission_name }}\">\n              </p>\n          {% endform %}\n          {% for account_plan in account_plans %}\n            <div class=\"plan-preview\" data-plan-id=\"{{account_plan.id}}\" style=\"{% if contract.plan.id != account_plan.id %} display:none; {% endif %}\">\n              <table class=\"plan_widget\">\n                {% if account_plan.features %}\n                  <tr>\n                    <th class=\"header\" colspan=\"3\">Features</th>\n                  </tr>\n                  {% for feature in account_plan.features %}\n                    <tr class=\"feature {% if feature.enabled? %} enabled {% else %} disabled {% endif %}\">\n                      <th>{{ feature.name }}</th>\n                      <td colspan=\"3\">\n                        {% if feature.enabled? %} {{\'tick.png\' | image_tag }} {% else %} {{\'cross.png\' | image_tag }}  {% endif %}\n                      </td>\n                  </tr>\n                  {% endfor %}\n                {% endif %}\n                {% if account_plan.paid? %}\n                  <tr><th class=\"header\" colspan=\"3\">Cost</th></tr>\n                  {% if account_plan.setup_fee != 0 %}\n                    <tr>\n                      <th>Setup Fee</th>\n                      <td colspan=\"2\">\n                       {{ account_plan.setup_fee }}\n                      </td>\n                    </tr>\n                  {% endif %}\n                  <tr>\n                    <th> Monthly Fee </th>\n                    <td colspan=\"2\">\n                      {{ account_plan.flat_cost }}\n                    </td>\n                  </tr>\n                {% endif %}\n              </table>\n            </div>\n          {% endfor %}\n        {% else %}\n          <h3>Your Plan</h3>\n          <div class=\"plan-preview\" data-plan-id=\"{{contract.plan.id}}\">\n            <table class=\"plan_widget\">\n              {% if account_plan.features %}\n                <tr>\n                  <th class=\"header\" colspan=\"3\">Features</th>\n                </tr>\n                {% for feature in account_plan.features %}\n                  <tr class=\"feature {% if feature.enabled? %} enabled {% else %} disabled {% endif %}\">\n                    <th>{{ feature.name }}</th>\n                    <td colspan=\"3\">\n                      {% if feature.enabled? %} {{\'tick.png\' | image_tag }} {% else %} {{\'cross.png\' | image_tag }}  {% endif %}\n                    </td>\n                </tr>\n                {% endfor %}\n              {% endif %}\n              {% if account_plan.paid? %}\n                <tr><th class=\"header\" colspan=\"3\">Cost</th></tr>\n                {% if account_plan.setup_fee != 0 %}\n                  <tr>\n                    <th>Setup Fee</th>\n                    <td colspan=\"2\">\n                     {{ account_plan.setup_fee }}\n                    </td>\n                  </tr>\n                {% endif %}\n                <tr>\n                  <th> Monthly Fee </th>\n                  <td colspan=\"2\">\n                    {{ account_plan.flat_cost }}\n                  </td>\n                </tr>\n              {% endif %}\n            </table>\n          </div>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'account_plans/index'),(53,2,2,20,'CMS::Builtin::Page',NULL,'Account Overview','account/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        {% if current_account.can.be_updated? %}\n          <a href=\"{{ current_account.edit_url }}\" class=\"pull-right\">\n            <i class=\"fa fa-pencil\"></i>\n            Edit Account\n          </a>\n          <div class=\"clearfix\"></div>\n        {% endif %}\n      </div>\n      <div class=\"panel-body panel-footer\">\n        <dl class=\"dl-horizontal wide\">\n          {% for field in current_account.fields %}\n            {% if field.value != \"\" and field.visible? %}\n              <dt>{{ field.label }}</dt>\n              <dd>{{ field }}</dd>\n            {% endif %}\n          {% endfor %}\n          <!-- add one field bound to \'user\' -->\n          <dt>{{ current_account.admin.fields.email.label }}</dt>\n          <dd>{{ current_account.admin.email }}</dd>\n        </dl>\n      </div>\n    </div>\n\n    <p><em>Please email to {{ provider.support_email | mail_to }} if\n    you have any problems with your account {% if current_account.can.be_deleted? %}\n    or you would like to cancel it. {% else %}. {% endif %}</em></p>\n  </div>\n</div>',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'account/show'),(54,2,2,20,'CMS::Builtin::Page',NULL,'Edit Account Details','account/edit','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        <a href=\"{{ urls.account_overview }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          Cancel\n        </a>\n      </div>\n      <div class=\"panel-body panel-footer\">\n\n        {% form \'account.personal_details\', current_account, class: \"form-horizontal\" %}\n\n          <fieldset class=\"inputs\" name=\"Contact Details\">\n            {% for field in current_account.fields %}\n              {% include \'field\' with field %}\n            {% endfor %}\n          </fieldset>\n\n          <fieldset>\n            <div class=\"form-group\">\n              <div class=\"col-md-10\">\n                <input class=\"btn btn-primary pull-right\" name=\"commit\" type=\"submit\" value=\"Update Account\" />\n              </div>\n            </div>\n          </fieldset>\n\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'account/edit'),(55,2,2,21,'CMS::Builtin::Page',NULL,'Users','accounts/users/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <table class=\"table panel panel-default\" id=\"users\">\n      <thead class=\"panel-heading\">\n        <tr>\n          <th>Name</th>\n          <th>Username</th>\n          <th>\n            {{ current_user.fields.email.label }}\n          </th>\n          <th>Role</th>\n          <th></th>\n        </tr>\n      </thead>\n      <tbody class=\"panel-body\">\n        {% for user in users %}\n          <tr>\n            <td>\n              {% if user == current_user %}\n                <span class=\"label label-primary\">YOU</span>\n              {% endif %}\n              {{ user.display_name }}\n            </td>\n            <td>{{ user.username }}</td>\n            <td>{{ user.email }}</td>\n            <td>{{ user.role }}</td>\n            <td>\n              {% if user.can.be_managed? %}\n                {% if current_user == user %}\n                  <a href=\"{{ urls.personal_details }}\" title=\"Edit user\">\n                    <i class=\"fa fa-pencil\"></i>\n                  </a>\n                {% else %}\n                  <a href=\"{{ user.edit_url }}\" title=\"Edit user\">\n                    <i class=\"fa fa-pencil\"></i>\n                  </a>\n                {% endif %}\n              {% endif %}\n\n\n            </td>\n          </tr>\n        {% endfor %}\n      </tbody>\n      <tfoot class=\"panel-footer\">\n        <tr>\n          <td colspan=\"4\">\n          </td>\n          <td>\n            {% if current_user.can.invite_users? %}\n              <span>{{ \'Invite new user\' | link_to: urls.new_invitation, class: \'btn btn-primary\' }}</span>\n            {% endif %}\n          </td>\n        </tr>\n      </tfoot>\n    </table>\n    {% include \'shared/pagination\' with pagination %}\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'accounts/users/index'),(56,2,2,21,'CMS::Builtin::Page',NULL,'User Edit','accounts/users/edit','<div class=\"row\">\n    <div class=\"col-md-9\">\n        {% include \'users_menu\' %}\n        <div class=\"panel panel-default\">\n            <div class=\"panel-heading important\">\n                <a href=\"{{ urls.users }}\">\n                    <i class=\"fa fa-chevron-left\"></i>\n                    Cancel\n                </a>\n                {% if user.can.be_destroyed? %}\n                    <span class=\"pull-right\">\n                        {{ \'<i class=\"fa fa-trash\"></i>\' | html_safe | link_to: user.url, method: \'delete\', confirm:  \"Are you sure you want to delete this user?\" }}\n                    </span>\n                {% endif %}\n            </div>\n            <div class=\"panel-body panel-footer\">\n                {% form \'user.edit\', user, class: \"form-horizontal\" %}\n                <fieldset class=\"inputs\" name=\"Contact Details\">\n                    {% for field in user.fields %}\n                        {% include \'field\' with field %}\n                    {% endfor %}\n                </fieldset>\n\n                <fieldset name=\"Change Password\">\n                    <div class=\"form-group\">\n                        <label for=\"inputPassword3\" class=\"col-md-4 control-label\">Password</label>\n                        <div class=\"col-md-6\">\n                            <input type=\"password\" id=\"user_password\" name=\"user[password]\" class=\"form-control\"\n                                   placeholder=\"Password\">\n                            {{ user.errors.password | inline_errors }}\n                        </div>\n                    </div>\n                    <div class=\"form-group\">\n                        <label for=\"inputPassword3\" class=\"col-md-4 control-label\">Password confirmation</label>\n                        <div class=\"col-md-6\">\n                            <input type=\"password\" id=\"user_password_confirmation\" name=\"user[password_confirmation]\"\n                                   class=\"form-control\" placeholder=\"Password\">\n                            {{ user.errors.password_confirmation | inline_errors }}\n                        </div>\n                    </div>\n                </fieldset>\n                {% if user.can.be_update_role? %}\n                    <fieldset name=\"Administrative\">\n                        <legend>\n                            <span> Administrative Role </span>\n                        </legend>\n                        {% for role in user.roles_collection %}\n                            <div class=\"radio\">\n                                <label>\n                                    <input\n                                            {% if user.role == role.name %}\n                                                checked=\"checked\"\n                                            {% endif %}\n                                            type=\"radio\" name=\"user[role]\" id=\"user_role_{{ role.name }}\"\n                                            value=\"{{ role.name }}\" checked>\n                                    {{ role.description }}\n                                </label>\n                            </div>\n                        {% endfor %}\n                    </fieldset>\n                {% endif %}\n                <div class=\"btn-toolbar pull-right\" role=\"toolbar\">\n                    <div class=\"btn-group\" role=\"group\">\n                        <input class=\"btn btn-primary\" name=\"commit\" type=\"submit\" value=\"Update User\">\n                    </div>\n                </div>\n                {% endform %}\n            </div>\n        </div>\n    </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'accounts/users/edit'),(57,2,2,22,'CMS::Builtin::Page',NULL,'Personal Details','user/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        <a href=\"{{ urls.users }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          All users\n        </a>\n      </div>\n      <div class=\"panel-body panel-footer\">\n        {% form \'user.personal_details\', user, class: \"form-horizontal\" %}\n          <fieldset>\n            <legend>\n              <span>User information</span>\n            </legend>\n            {% for field in user.fields %}\n              {% include \'field\' with field %}\n            {% endfor %}\n          </fieldset>\n\n          {% if user.using_password? %}\n            <fieldset>\n              <legend>\n                <span>Provide your current password</span>\n              </legend>\n              <div class=\"form-group {{ user.errors.current_password | error_class: \'has-error\' }}\">\n                <label for=\"user_current_password\" class=\"col-md-4 control-label\">\n                  Current Password\n                </label>\n                <div class=\"col-md-6\">\n                  <input\n                    id=\"user_current_password\"\n                    name=\"user[current_password]\"\n                    type=\"password\"\n                    class=\"form-control\">\n                  {{ user.errors.current_password | inline_errors: \'help-block\' }}\n                </div>\n              </div>\n            </fieldset>\n\n            <fieldset>\n              <legend>\n                <span>Change password</span>\n              </legend>\n              <div class=\"form-group {{ user.errors.password | error_class: \'has-error\' }}\">\n                <label for=\"user_password_confirmation\" class=\"col-md-4 control-label\">\n                  Password\n                </label>\n                <div class=\"col-md-6\">\n                  <input\n                    id=\"user_password\"\n                    name=\"user[password]\"\n                    type=\"password\"\n                    class=\"form-control\">\n                  {{ user.errors.password | inline_errors: \'help-block\' }}\n                </div>\n              </div>\n\n              <div class=\"form-group {{ user.errors.password_confirmation | error_class: \'has-error\' }}\">\n                <label for=\"user_password_confirmation\" class=\"col-md-4 control-label\">\n                  Password confirmation\n                </label>\n                <div class=\"col-md-6\">\n                  <input\n                    id=\"user_password_confirmation\"\n                    name=\"user[password_confirmation]\"\n                    type=\"password\"\n                    class=\"form-control\">\n                  {{ user.errors.password_confirmation | inline_errors: \'help-block\' }}\n                </div>\n              </div>\n            </fieldset>\n          {% endif %}\n\n          <fieldset>\n            <div class=\"form-group\">\n              <div class=\"col-md-10\">\n                <input\n                  class=\"btn btn-primary pull-right\"\n                  name=\"commit\"\n                  type=\"submit\"\n                  value=\"Update Personal Details\">\n              </div>\n            </div>\n          </fieldset>\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'user/show'),(58,2,2,23,'CMS::Builtin::Page',NULL,'Search','search/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n       {% if search.query %}\n          Search \'{{ search.query }}\'\n        {% else %}\n          Search\n        {% endif %}\n      </div>\n      <div class=\"panel-body panel-footer\">\n        {% form \'search\', search, { class: \'form-horizontal\' } %}\n          <fieldset>\n            <div class=\"form-group\">\n              <div class=\"col-md-4 col-md-push-3\">\n                <input name=\"q\" type=\"text\" id=\"searchAgainBox\" title=\"Search\"\n                     class=\"form-control\" tabindex=\'1\' value=\"{{ search.query }}\"\n                     autofocus=\"autofocus\" />\n                <!--\n                <div class=\"checkbox\">\n\n                  <label>\n                    <input type=\"checkbox\" name=\"star\" title=\"Wildcard search\" tabindex=\'2\' value=\"1\"/> use wildcards?\n                  </label>\n                </div>\n                -->\n              </div>\n              <div class=\"col-md-2 col-md-push-3\">\n                <button type=\"submit\" class=\"btn btn-success\" tabindex=\'3\'>Search</button>\n              </div>\n            </div>\n\n          </fieldset>\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>\n\n<style scoped>\n  .searchResultsList .match {\n    font-weight: bold;\n  }\n  .searchResultsList .kind {\n    display: inline-block;\n    min-width: 5em;\n    font-weight: bold;\n    padding-right: 0.5em;\n  }\n</style>\n\n{% if search.results %}\n  <div class=\"row\">\n    <div class=\"col-md-9\">\n\n      <dl class=\"searchResultsList\">\n        {% if search.query == present %}\n          <h4 class=\"help-block\">{{ search.total_found }} documents matched \'{{ search.query }}\'.</h4>\n        {% endif %}\n\n       {% for result in search.results %}\n        <dt>\n          <span class=\"kind\"> [ {{ result.kind | capitalize}} ] </span>\n          {{ result.title | link_to: result.url }}\n        </dt>\n        <dd>\n          {{ result.description }}\n        </dd>\n       {% endfor %}\n      </dl>\n      {% include \'shared/pagination\' with pagination %}\n    </div>\n  </div>\n{% endif %}\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'search/index'),(59,2,2,24,'CMS::Builtin::Page',NULL,'Sent invitations','invitations/index','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <table class=\"table panel panel-default\" id=\"invitations\">\n      <thead class=\"panel-heading\">\n        <tr>\n          <th>Recipient</th>\n          <th>Sent</th>\n          <th>Accepted?</th>\n          <th colspan=\"2\"></th>\n        </tr>\n      </thead>\n      <tbody class=\"panel-body\">\n        {% if invitations.size > 0 %}\n          {% for invitation in invitations %}\n            <tr id=\"invitation_{{ invitation.id }}\">\n              <td>{{ invitation.email }}</td>\n              <td>\n                {{ invitation.sent_at | date: i18n.short_date }}\n              </td>\n              <td>\n                {% if invitation.accepted? %}\n                  yes, on {{invitation.accepted_at | format: i18n.short_date }}\n                {% else %}\n                  no\n                {% endif %}\n              </td>\n              <td>\n                  {% unless invitation.accepted? %}\n                    {{ \"Resend\" | update_button: invitation.resend_url, class: \'btn btn-link pull-right\' }}\n                  {% endunless %}\n\n              </td>\n              <td>\n                  {% if current_user.can.invite_users? %}\n                      {{ \'<i class=\"fa fa-trash pull-right\"></i>\' | html_safe | link_to: invitation.url, class: \'pull-right btn btn-link\', method: \'delete\' }}\n                  {% endif %}\n              </td>\n            </tr>\n          {% endfor %}\n        {% else %}\n          <tr>\n            <td colspan=\"5\">No invitations</td>\n          </tr>\n        {% endif %}\n      </tbody>\n      <tfoot class=\"panel-footer\">\n        <tr>\n          <th colspan=\"5\">\n            {% if current_user.can.invite_users? %}\n              {{ \'Invite new user\' | link_to: urls.new_invitation, class: \'btn btn-primary pull-right\' }}\n            {% endif %}\n          </th>\n        </tr>\n      </tfoot>\n    </table>\n    {% include \'shared/pagination\' with pagination %}\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'invitations/index'),(60,2,2,24,'CMS::Builtin::Page',NULL,'Create new invitations','invitations/new','<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        <a href=\"{{ urls.invitations }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          Cancel\n        </a>\n        New invitation\n      </div>\n      <div class=\"panel-body panel-footer\">\n        {% form \'invitation.create\', invitation, class: \"form-horizontal\" %}\n          <fieldset>\n            <div class=\"form-group\">\n              <label for=\"invitation_email\" class=\"control-label col-md-4\">\n                Send invitation to\n              </label>\n              <div class=\"col-md-6\">\n                <input id=\"invitation_email\" maxlength=\"255\"\n                     name=\"invitation[email]\"\n                     type=\"email\"\n                     value=\"{{ invitation.email }}\"\n                     class=\"{{ invitation.errors.email | error_class }} form-control\"/>\n                    {{ invitation.errors.email | inline_errors }}\n                <p class=\"help-block\">\n                  Email address of a colleague or friend you want to invite to use this account.\n                </p>\n              </div>\n            </div>\n          </fieldset>\n          <div class=\"form-group\">\n            <div class=\"col-md-10\">\n              <input name=\"commit\" class=\"btn btn-success pull-right\" type=\"submit\" value=\"Invite User\">\n            </div>\n          </div>\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>',NULL,NULL,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',7,NULL,'',NULL,0,'invitations/new'),(61,2,2,25,'CMS::Builtin::Page',NULL,'Edit Billing Address Form','accounts/payment_gateways/edit','{% disable_client_cache %}\n\n<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n    <div class=\"panel panel-default\">\n      {% unless current_account.requires_credit_card_now? %}\n      <div class=\"panel-heading important\">\n        <a href=\"{{ urls.payment_details }}\">\n          <i class=\"fa fa-chevron-left\"></i>\n          Cancel\n        </a>\n      </div>\n      {%  endunless %}\n      <div class=\"panel-body\">\n\n        {% if current_account.requires_credit_card_now? %}\n          <div class=\"wide_dashboard_box round\">\n            <p class=\"alert-warning\">\n              You have subscribed to a paid plan. To complete your signup, please fill in your credit card details.\n            </p>\n          </div>\n        {% endif %}\n\n        {% if provider.payment_gateway.braintree_blue? %}\n\n          <div class=\"wide_dashboard_box round\">\n            <h3>Payment Details</h3>\n\n            <p>Update your credit card details here to set up monthly billing for your {{ provider.name }} service. You\'ll be charged monthly on 7th of the following month and receive email notification about a successful payment along with the invoice.</p>\n\n            {% braintree_customer_form %}\n\n          </div>\n\n        {% else %}\n\n          {% form \'account.billing_address\', current_account.billing_address, class: \"form-horizontal\" %}\n\n            <fieldset class=\"inputs\" name=\"Billing Address\">\n              <legend><span>Billing Address</span></legend>\n              {% for field in current_account.billing_address.fields %}\n                {% include \'field\' with field %}\n              {% endfor %}\n            </fieldset>\n\n            <fieldset>\n              <div class=\"form-group\">\n                <div class=\"col-md-10\">\n                  <input class=\"btn btn-primary pull-right\" name=\"commit\" type=\"submit\" value=\"Save\" />\n                </div>\n              </div>\n            </fieldset>\n\n          {% endform %}\n\n        {% endif %}\n\n      </div>\n      <div class=\"panel-footer\">\n        <p>By <strong>Entering Credit Card details</strong> you agree to the <a href=\"{{ urls.credit_card_terms }}\" id=\"terms-link\">Terms of Service</a>, <a href=\"{{ urls.credit_card_privacy }}\" id=\"privacy-link\">Privacy</a> and <a href=\"{{ urls.credit_card_refunds }}\" id=\"refunds-link\">Refund</a>.</p>\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:47','2026-09-10 15:43:47',7,NULL,'',NULL,0,'accounts/payment_gateways/edit'),(62,2,2,25,'CMS::Builtin::Page',NULL,'Show User\'s Payment Details','accounts/payment_gateways/show','{% disable_client_cache %}\n\n<div class=\"row\">\n  <div class=\"col-md-9\">\n    {% include \'users_menu\' %}\n\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading important\">\n        <div class=\"pull-right\">\n          {% comment %}\n            We render a link to edit the user billing information, depending on your payment gateway.\n            In case of Braintree, billing address and credit card are collected in the same form.\n            Stripe on the other hand use two separate forms.\n          {% endcomment %}\n          {% case provider.payment_gateway.type %}\n\n          {% when \"braintree_blue\" %}\n            {% if current_account.has_billing_address? and current_account.credit_card_stored? %}\n              <a href=\"{{ current_account.edit_braintree_blue_credit_card_details_url }}\">\n                <i class=\"icon-pencil\"></i>\n                Edit Credit Card Details and Billing Address\n              </a>\n            {% endif %}\n\n          {% when \"stripe\" %}\n            {% if current_account.has_billing_address? %}\n              <a href=\"{{ current_account.edit_stripe_billing_address_url }}\">\n                <i class=\"fa fa-pencil\"></i>\n                Edit billing address\n              </a>\n            {% endif %}\n\n          {% endcase %}\n        </div>\n        <div class=\"clearfix\"></div>\n      </div>\n\n      <div class=\"panel-body\">\n        {% comment %}\n          We render the user\'s billing address and credit card details only after they have\n          added it previously. Otherwise, we render a link to do so.\n        {% endcomment %}\n        {% if current_account.has_billing_address? %}\n          <dl class=\"dl-horizontal\" id=\"billing_address\">\n            <dt>Address</dt>\n            <dd>{{ current_account.billing_address.address }}</dd>\n\n            <dt>Zip</dt>\n            <dd>{{ current_account.billing_address.zip }}</dd>\n\n            <dt>City</dt>\n            <dd>{{ current_account.billing_address.city }}</dd>\n\n            <dt>State</dt>\n            <dd>{{ current_account.billing_address.state }}</dd>\n\n            <dt>Country</dt>\n            <dd>{{ current_account.billing_address.country }}</dd>\n\n            <dt>Phone</dt>\n            <dd>{{ current_account.billing_address.phone }}</dd>\n\n            {% if current_account.credit_card_stored? %}\n              <dt>Credit card number</dt>\n              <dd>{{ current_account.credit_card_display_number }}</dd>\n\n              {% unless provider.payment_gateway.authorize_net? %}\n                <dt>Expiration date</dt>\n                <dd>{{ current_account.credit_card_expiration_date }}<dd>\n              {% endunless %}\n            {% endif %}\n          </dl>\n        {% endif %}\n\n        {% case provider.payment_gateway.type %}\n\n        {% when \"braintree_blue\" %}\n          {% unless current_account.has_billing_address? and current_account.credit_card_stored? %}\n            <a href=\"{{ current_account.edit_braintree_blue_credit_card_details_url }}\">\n              Add Credit Card Details and Billing Address\n            </a>\n          {% endunless %}\n\n        {% comment %} Authorize.net combines billing address + cc details in 1 external form {% endcomment %}\n        {% when \"authorize_net\" %}\n          {% if current_account.credit_card_stored? %}\n            {% authorize_net_form \"Edit Credit Card Details\" %}\n          {% else %}\n            {% authorize_net_form \"Add Credit Card Details\" %}\n          {% endif %}\n\n        {% comment %} Stripe renders the form in place once a billing address has been added {% endcomment %}\n        {% when \"stripe\" %}\n          {% if current_account.has_billing_address? %}\n            {% stripe_form %}\n          {% else %}\n            <p><a href=\"{{ current_account.edit_stripe_billing_address_url }}\">First add a billing address</a></p>\n          {% endif %}\n\n        {% endcase %}\n      </div>\n\n      <div class=\"panel-footer\">\n        <p>By <strong>Entering Credit Card details</strong> you agree to the <a href=\"{{ urls.credit_card_terms }}\" id=\"terms-link\">Terms of Service</a>, <a href=\"{{ urls.credit_card_privacy }}\" id=\"privacy-link\">Privacy</a> and <a href=\"{{ urls.credit_card_refunds }}\" id=\"refunds-link\">Refund</a>.</p>\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:47','2026-09-10 15:43:47',7,NULL,'',NULL,0,'accounts/payment_gateways/show'),(63,2,2,26,'CMS::Builtin::Page',NULL,'Not Found','errors/not_found','<h1>Not Found</h1>\n<p>Sorry. We can\'t find what you\'re looking for.</p>\n',NULL,NULL,NULL,'2026-09-10 15:43:47','2026-09-10 15:43:47',8,NULL,'',NULL,0,'errors/not_found'),(64,2,2,26,'CMS::Builtin::Page',NULL,'Internal Server Error','errors/internal_server_error','<h1>Internal Error</h1>\n<p>Sorry, but something went wrong.</p>\n',NULL,NULL,NULL,'2026-09-10 15:43:47','2026-09-10 15:43:47',8,NULL,'',NULL,0,'errors/internal_server_error'),(65,2,2,26,'CMS::Builtin::Page',NULL,'Forbidden','errors/forbidden','<h1>Access Denied</h1>\n<p>Sorry, you do not have permission to access this page.</p>\n',NULL,NULL,NULL,'2026-09-10 15:43:47','2026-09-10 15:43:47',8,NULL,'',NULL,0,'errors/forbidden'),(66,2,2,27,'CMS::Builtin::Page',NULL,'Invitation signup form','accounts/invitee_signups/show','<div class=\"row\">\n  <div class=\"col-md-9\">\n    <div class=\"panel panel-default\">\n      <div class=\"panel-heading\">\n        <i class=\"fa fa-user\"></i>\n        Invitation sign in\n      </div>\n      <div class=\"panel-body\">\n\n        {% include \'login/sso\' %}\n\n        {% form \'invitation_signup\', user, { class: \'form-horizontal\' } %}\n\n          <fieldset>\n\n            {% for field in user.fields %}\n              {% include \'field\' with field %}\n            {% endfor %}\n\n            {% if user.password_required? %}\n              <div class=\"form-group {{ user.errors.password | error_class: \'has-error\' }}\" id=\"user_password_input\">\n                <label for=\"user_password\" class=\"control-label col-md-4\">Password</label>\n                <div class=\"col-md-6\">\n                  <input id=\"user_password\" name=\"user[password]\" tabindex=\"1\"\n                         autofocus=\"autofocus\" type=\"password\" class=\"form-control\">\n                  {{ user.errors.password | inline_errors: \'inline-errors\' }}\n                </div>\n              </div>\n\n              <div class=\"form-group {{ user.errors.password_confirmation | error_class: \'has-error\' }}\" id=\"user_password_confirmation_input\">\n                <label for=\"user_password_confirmation\" class=\"control-label col-md-4\">\n                  Password confirmation\n                </label>\n                <div class=\"col-md-6\">\n                  <input id=\"user_password_confirmation\" name=\"user[password_confirmation]\" tabindex=\"2\"\n                         type=\"password\" class=\"form-control\">\n                  {{ user.errors.password_confirmation | inline_errors: \'inline-errors\' }}\n                </div>\n              </div>\n            {% endif %}\n\n          </fieldset>\n\n          {% include \'signup_licence\' %}\n\n          <fieldset>\n            <div class=\"form-group\">\n              <div class=\"col-md-10\">\n                <input name=\"commit\" type=\"submit\" value=\"Sign up\" class=\"btn btn-success btn-lg pull-right\">\n              </div>\n            </div>\n          </fieldset>\n        {% endform %}\n      </div>\n    </div>\n  </div>\n</div>\n',NULL,NULL,NULL,'2026-09-10 15:43:47','2026-09-10 15:43:47',7,NULL,'',NULL,0,'accounts/invitee_signups/show');
