INSERT INTO `cms_templates_versions` VALUES (1,2,2,NULL,'CMS::Template::Version',NULL,'Main layout','main_layout','<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <title>\n      {% if page.title %}\n        {{ page.title }}\n      {% else %}\n        {{ provider.name }}\n      {% endif %}\n    </title>\n\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n\n    {% csrf %}\n    {{ \'/css/bootstrap.css\' | stylesheet_link_tag }}\n    {% cdn_asset /font-awesome/4.3.0/css/font-awesome.css %}\n\n    {% cdn_asset /jquery/3.5.0/jquery.min.js %}\n\n    {{ \'/javascripts/bootstrap.min.js\' | javascript_include_tag }}\n    {{ \'/javascripts/vendor/colorbox/jquery.colorbox-patched.js\' | javascript_include_tag }}\n    {{ \'/javascripts/3scale_v2.js\' | javascript_include_tag }}\n    {{ \'/javascripts/excanvas.compiled.js\' | javascript_include_tag }}\n\n    {{ content_of.stylesheets | html_safe }}\n    {{ \'/css/default.css\' | stylesheet_link_tag }}\n\n    {{ content_of.javascripts | html_safe }}\n  </head>\n\n  <body>\n    <header role=\"banner\">\n      <nav class=\"navbar navbar-fixed-top navbar-inverse\" role=\"navigation\">\n        <div class=\"container tabbed\">\n          <div class=\"navbar-header\">\n            <button type=\"button\" class=\"navbar-toggle collapsed\" data-toggle=\"collapse\" data-target=\"#navbar-1\">\n              <span class=\"sr-only\">Toggle navigation</span>\n              <span class=\"icon-bar\"></span>\n              <span class=\"icon-bar\"></span>\n              <span class=\"icon-bar\"></span>\n            </button>\n            <a class=\"navbar-brand\" href=\"/\">{{  provider.name }}</a>\n          </div>\n          {% include \'submenu\'%}\n        </div>\n      </nav>\n\n      {% comment %}\n        WARNING: Please note that if you remove the block below\n        you developer portal will stop displaying errors and\n        information messages such as \'Invalid password\' on\n        login form or similar.\n      {% endcomment %}\n\n        <div id=\"flash-messages\">\n          {% for message in flash.messages %}\n            <div class=\"navbar navbar-fixed-top navbar-default alert alert-{{ message.type }}\" data-dismiss=\"alert\">\n              <div class=\"container\">\n                  <button type=\"button\" class=\"close\"  aria-hidden=\"true\">&times;</button>\n                  {{ message.text }}\n              </div>\n            </div>\n          {% endfor %}\n        </div>\n    </header>\n\n    <main id=\"main-content\" role=\"main\">\n      {% if request.path == \'/\' %}\n        {% content %}\n      {% else %}\n        <div class=\"full\">\n          <div class=\"container\">\n            {% content %}\n          </div>\n        </div>\n      {% endif %}\n    </main>\n\n    <footer role=\"contentinfo\">\n      <div class=\"container\">\n        <ul class=\"list-inline pull-right\">\n          <li>&copy; {{ today.year }} {{ provider.name }},</li>\n          <li><a class=\"powered-by\" href=\"http://3scale.net/\">Powered by 3scale</a></li>\n        </ul>\n      </div>\n    </footer>\n\n    <!-- JS and analytics only. -->\n    {% include \'analytics\' %}\n  </body>\n</html>\n',NULL,1,NULL,'2026-09-10 15:43:41','2026-09-10 15:43:41',NULL,7,'CMS::Template',NULL,'',NULL,0),(2,2,2,NULL,'CMS::Template::Version',NULL,'Main layout','main_layout',NULL,'<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <title>\n      {% if page.title %}\n        {{ page.title }}\n      {% else %}\n        {{ provider.name }}\n      {% endif %}\n    </title>\n\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n\n    {% csrf %}\n    {{ \'/css/bootstrap.css\' | stylesheet_link_tag }}\n    {% cdn_asset /font-awesome/4.3.0/css/font-awesome.css %}\n\n    {% cdn_asset /jquery/3.5.0/jquery.min.js %}\n\n    {{ \'/javascripts/bootstrap.min.js\' | javascript_include_tag }}\n    {{ \'/javascripts/vendor/colorbox/jquery.colorbox-patched.js\' | javascript_include_tag }}\n    {{ \'/javascripts/3scale_v2.js\' | javascript_include_tag }}\n    {{ \'/javascripts/excanvas.compiled.js\' | javascript_include_tag }}\n\n    {{ content_of.stylesheets | html_safe }}\n    {{ \'/css/default.css\' | stylesheet_link_tag }}\n\n    {{ content_of.javascripts | html_safe }}\n  </head>\n\n  <body>\n    <header role=\"banner\">\n      <nav class=\"navbar navbar-fixed-top navbar-inverse\" role=\"navigation\">\n        <div class=\"container tabbed\">\n          <div class=\"navbar-header\">\n            <button type=\"button\" class=\"navbar-toggle collapsed\" data-toggle=\"collapse\" data-target=\"#navbar-1\">\n              <span class=\"sr-only\">Toggle navigation</span>\n              <span class=\"icon-bar\"></span>\n              <span class=\"icon-bar\"></span>\n              <span class=\"icon-bar\"></span>\n            </button>\n            <a class=\"navbar-brand\" href=\"/\">{{  provider.name }}</a>\n          </div>\n          {% include \'submenu\'%}\n        </div>\n      </nav>\n\n      {% comment %}\n        WARNING: Please note that if you remove the block below\n        you developer portal will stop displaying errors and\n        information messages such as \'Invalid password\' on\n        login form or similar.\n      {% endcomment %}\n\n        <div id=\"flash-messages\">\n          {% for message in flash.messages %}\n            <div class=\"navbar navbar-fixed-top navbar-default alert alert-{{ message.type }}\" data-dismiss=\"alert\">\n              <div class=\"container\">\n                  <button type=\"button\" class=\"close\"  aria-hidden=\"true\">&times;</button>\n                  {{ message.text }}\n              </div>\n            </div>\n          {% endfor %}\n        </div>\n    </header>\n\n    <main id=\"main-content\" role=\"main\">\n      {% if request.path == \'/\' %}\n        {% content %}\n      {% else %}\n        <div class=\"full\">\n          <div class=\"container\">\n            {% content %}\n          </div>\n        </div>\n      {% endif %}\n    </main>\n\n    <footer role=\"contentinfo\">\n      <div class=\"container\">\n        <ul class=\"list-inline pull-right\">\n          <li>&copy; {{ today.year }} {{ provider.name }},</li>\n          <li><a class=\"powered-by\" href=\"http://3scale.net/\">Powered by 3scale</a></li>\n        </ul>\n      </div>\n    </footer>\n\n    <!-- JS and analytics only. -->\n    {% include \'analytics\' %}\n  </body>\n</html>\n',1,NULL,'2026-09-10 15:43:41','2026-09-10 15:43:41',NULL,7,'CMS::Template',NULL,'',NULL,0),(3,2,2,NULL,'CMS::Template::Version',NULL,'Error layout','error','<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <title>{{ page.title }}</title>\n\n    <style>\n      /* normalize.css 2012-03-11T12:53 UTC - http://github.com/necolas/normalize.css */\n      /* =============================================================================\n         HTML5 display definitions\n         ========================================================================== */\n      /*\n       * Corrects block display not defined in IE6/7/8/9 & FF3\n       */\n      /* line 21, ../../app/assets/stylesheets/vendor/normalize.scss */\n      article,\n      aside,\n      details,\n      figcaption,\n      figure,\n      footer,\n      header,\n      hgroup,\n      nav,\n      section,\n      summary {\n        display: block;\n      }\n\n      /*\n       * Corrects inline-block display not defined in IE6/7/8/9 & FF3\n       */\n      /* line 31, ../../app/assets/stylesheets/vendor/normalize.scss */\n      audio,\n      canvas,\n      video {\n        display: inline-block;\n        *display: inline;\n        *zoom: 1;\n      }\n\n      /*\n       * Prevents modern browsers from displaying \'audio\' without controls\n       * Remove excess height in iOS5 devices\n       */\n      /* line 42, ../../app/assets/stylesheets/vendor