ss */\n      #content {\n        padding: 1em;\n      }\n\n      /* line 52, ../../app/assets/stylesheets/error.scss */\n      #footer {\n        margin-top: 2em;\n        padding: 1.5em 3em 1.65em 3em;\n        margin-left: -3em;\n        margin-bottom: -3em;\n        border-top: 1px solid gray;\n        width: 100%;\n      }\n      /* line 62, ../../app/assets/stylesheets/error.scss */\n      #footer > ul {\n        margin: 0;\n        padding: 0;\n        border: 0;\n        overflow: hidden;\n        *zoom: 1;\n      }\n      /* line 60, ../../../../../system_production/shared/bundle/ruby/1.9.1/gems/compass-0.12.2/frameworks/compass/stylesheets/compass/typography/lists/_horizontal-list.scss */\n      #footer > ul li {\n        list-style-image: none;\n        list-style-type: none;\n        margin-left: 0;\n        white-space: nowrap;\n        display: inline;\n        float: left;\n        padding-left: 4px;\n        padding-right: 4px;\n      }\n      /* line 48, ../../../../../system_production/shared/bundle/ruby/1.9.1/gems/compass-0.12.2/frameworks/compass/stylesheets/compass/typography/lists/_horizontal-list.scss */\n      #footer > ul li:first-child, #footer > ul li.first {\n        padding-left: 0;\n      }\n      /* line 49, ../../../../../system_production/shared/bundle/ruby/1.9.1/gems/compass-0.12.2/frameworks/compass/stylesheets/compass/typography/lists/_horizontal-list.scss */\n      #footer > ul li:last-child {\n        padding-right: 0;\n      }\n      /* line 50, ../../../../../system_production/shared/bundle/ruby/1.9.1/gems/compass-0.12.2/frameworks/compass/stylesheets/compass/typography/lists/_horizontal-list.scss */\n      #footer > ul li.last {\n        padding-right: 0;\n      }\n      /* line 65, ../../app/assets/stylesheets/error.scss */\n      #footer > ul a {\n        display: -moz-inline-stack;\n        display: inline-block;\n        vertical-align: middle;\n        *vertical-align: auto;\n        zoom: 1;\n        *display: inline;\n      }\n      /* line 68, ../../app/assets/stylesheets/error.scss */\n      #footer > ul img {\n        vertical-align: middle;\n      }\n      /* line 72, ../../app/assets/stylesheets/error.scss */\n      #footer > ul .last {\n        float: right;\n      }\n   </style>\n  </head>\n\n  <body>\n    <div id=\"wrapper\">\n      <div id=\"content\">\n        <!-- logo -->\n        {% logo %}\n        <!-- /logo -->\n        {% content %}\n      </div>\n      <!-- footer -->\n      {% oldfooter %}\n      <!-- /footer -->\n    </div>\n  </body>\n</html>\n',1,NULL,'2026-09-10 15:43:41','2026-09-10 15:43:41',NULL,8,'CMS::Template',NULL,'',NULL,0),(5,2,2,3,'CMS::Template::Version','/','Homepage',NULL,'{% disable_client_cache %}\n\n<header class=\"jumbotron page-header\">\n  <div class=\"container\">\n    <div class=\"row\">\n      <div class=\"col-md-12\">\n        <h1>Echo API</h1>\n      </div>\n    </div>\n  </div>\n</header>\n\n{% if current_user %}\n  <section class=\"start\">\n  <div class=\"container\">\n  <div class=\"row\">\n    <div class=\"col-md-6\">\n      <h1>Your API Key</h1>\n      <br>\n      <p class=\"lead\">\n       This is your API key that should be kept secret. Use it to authenticate and report the calls you make to the Echo API.\n      </p>\n    </div>\n    <div class=\"col-md-6\" style=\"padding-top:2em;\">\n      <div class=\"panel panel-default\" id=\"access-details\">\n        <div class=\"panel-heading\">\n          <i class=\"fa fa-key\"></i>\n          Credentials\n          {% if current_account.applications.size > 0 %}\n            <a class=\"pull-right\" href=\"{{ urls.applications }}\" title=\"Applications\">\n              <i class=\"fa fa-chevron-right\"></i>\n            </a>\n          {% endif %}\n        </div>\n        <div class=\"panel-body panel-footer\">\n          {% if current_account.applications.size == 0 %}\n            <a href=\"{{ urls.new_application }}\" class=\"btn btn-primary\">Create Application</a>\n          {% elsif current_account.applications.size == 1 %}\n            {% assign app = current_account.applications.first %}\n\n            {% if app.user_key_mode? %}\n              <dl class=\"dl-horizontal\">\n                <dt>App name</dt>\n                <dd><a href=\"{{ app.url }}\">{{ app.name }}</a></dd>\n                <dt>Key</dt>\n                <dd>\n                  <code>{{ app.user_key }}</code>\n                  <p>Add this as a <code>user_key</code> parameter to your API calls to authenticate.</p>\n                </dd>\n              </dl>\n\n            {% elsif app.app_id_mode? %}\n              <dl class=\"dl-horizontal\">\n                <dt>App name</dt>\n                <dd><a href=\"{{ app.url }}\">{{ app.name }}</a></dd>\n                <dt>App ID</dt>\n                <dd><code>{{ app.application_id }}</code></dd>\n                <dt>Key</dt>\n                <dd><code>{{ app.keys.first }}</code></dd>\n              </dl>\n\n            {% elsif app.oauth_mode? %}\n              <dl class=\"dl-horizontal\">\n                <dt>App name</dt>\n                <dd><a href=\"{{ app.url }}\">{{ app.name }}</a></dd>\n                <dt>Client ID</dt>\n                <dd><code>{{ app.application_id }}</code></dd>\n                <dt>Client Secret</dt>\n                <dd><code>{{ app.keys.first }}</code></dd>\n              </dl>\n            {% endif %}\n\n            {% if app.trial? %}\n              <div class=\"alert alert-warning\">\n                <h3>Trial period</h3>\n                <p>{{ app.remaining_trial_period_days }} days remaining.</p>\n              </div>\n            {% endif %}\n\n          {% elsif current_account.applications.size > 1 %}\n            <a href=\"{{ urls.applications }}\" class=\"btn btn-primary\">See your Applications & their credentials</a>\n          {% endif %}\n          </div>\n        </div>\n      </div>\n    </div>\n\n  </div>\n  </section>\n\n{% else %}\n\n  <section class=\"sell\">\n    <div class=\"container\">\n      <div class=\"row\">\n        <div class=\"col-md-4\">\n          <h3>Register</h3>\n          <p>\n          <i class=\"fa fa-sign-in fa-3x pull-left\"></i>\n          Register to the developer portal to use the Echo API\n          </p>\n        </div>\n        <div class=\"col-md-4\">\n          <h3>Get your API key</h3>\n          <p>\n          <i class=\"fa fa-key fa-3x pull-left\"></i>\n          Use your API key to authenticate and report the calls you make\n          </p>\n        </div>\n       <div class=\"col-md-4\">\n        <h3>Create your app</h3>\n         <p>\n         <i class=\"fa fa-code fa-3x pull-left\"></i>\n         Start coding and create awesome applications with the Echo API\n         </p>\n        </div>\n       </div>\n      </div>\n  </section>\n\n  <section class=\"plans\" id=\"plans\">\n    <div class=\"container\">\n      <h1>Pick your plan</h1>\n      <br/>\n      <div class=\"row\">\n        {% for plan in provider.services.api.application_plans %}\n          <div class=\"col-md-6\">\n            <article class=\"panel panel-default\">\n              <div class=\"panel-heading\">\n                <strong>{{ plan.name }}</strong>\n              </div>\n              <div class=\"panel-body\">\n                <div class=\"row\">\n\n                  {% if plan.features == present %}\n                    <div class=\"col-md-6\">\n                      <h5>Features</h5>\n                      <ul class=\"features list-unstyled\">\n                        {% for feature in plan.features %}\n                          <li>\n                            <i class=\"fa fa-check\"></i>\n                            {{ feature.name }}\n                          </li>\n                        {% endfor %}\n                      </ul>\n                    </div>\n                  {% endif %}\n\n                  <div class=\"col-md-6\">\n                    <h5>Limits</h5>\n                    <ul class=\"limits list-unstyled\">\n                      {% if plan.usage_limits == present %}\n                        {% for limit in plan.usage_limits %}\n                          <li>\n                            <i class=\"fa fa-signal\"></i>\n                            {{ limit.metric.name }} &ndash; {{ limit.value }} {{ limit.metric.unit }}s per {{ limit.period }}\n                          </li>\n                        {% endfor %}\n                      {% else %}\n                        <li>\n                          <i class=\"fa fa-signal\"></i>\n                          No limits\n                        </li>\n                      {% endif %}\n                    </ul>\n                  </div>\n\n                </div>\n              </div>\n                <div class=\"panel-footer\">\n                <div class=\"row\">\n                  <div class=\"col-md-12\">\n\n                    <a class=\"btn btn-success pull-right\" href=\"{{ urls.signup }}?{{ plan | to_param }}\">Signup to plan {{ plan.name }}</a>\n                  </div>\n                </div>\n\n              </div>\n            </article>\n          </div>\n        {% endfor %}\n      </div>\n    </div>\n  </section>\n{% endif %}\n\n<section class=\"invert\">\n  <div class=\"container\">\n    <h1>Run your requests</h1>\n    <div class=\"row\">\n\n      <div class=\"col-md-12\">\n        <h3><code style=\"display:block\">$ curl -v https://echo-api.3scale.net</code></h3>\n        <br/>\n        <div class=\"row\">\n          <div class=\"col-md-6\">\n            <div class=\"panel panel-default\">\n              <div class=\"panel-heading\">\n                Request\n              </div>\n              <div class=\"panel-body panel-footer\">\n                <pre>\n&gt; GET / HTTP/1.1\n&gt; User-Agent: curl/7.27.0\n&gt; Host: https://echo-api.3scale.net/echo\n&gt; Accept: */*\n&gt;\n                </pre>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-6\">\n            <div class=\"panel panel-default\">\n              <div class=\"panel-heading\">\n                Response\n              </div>\n              <div class=\"panel-body panel-footer\">\n                <pre>\n&lt; HTTP/1.1 200 OK\n&lt; Content-Type: text/plain; charset=utf-8\n&lt; Connection: close\necho\n\n                </pre>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n',NULL,1,'text/html','2026-09-10 15:43:42','2026-09-10 15:43:42',7,9,'CMS::Template',NULL,NULL,NULL,0),(6,2,2,3,'CMS::Template::Version','/docs','Documentation',NULL,'{% disable_client_cache %}\n\n{% content_for javascripts %}\n    {{ \'active_docs.js\' | javascript_include_tag }}\n{% endcontent_for %}\n\n{% assign spec = provider.api_specs.first %}\n\n<h1>Documentation</h1>\n\n<div class=\"swagger-section\">\n  <div id=\"message-bar\" class=\"swagger-ui-wrap\">&nbsp;</div>\n  <div id=\"swagger-ui-container\" class=\"swagger-ui-wrap\"></div>\n</div>\n\n<script type=\"text/javascript\">\n  (function () {\n    var url = \"{{spec.url}}\";\n    var serviceEndpoint = \"{{spec.api_product_production_public_base_url}}\"\n    SwaggerUI({ url: url, dom_id: \"#swagger-ui-container\" }, serviceEndpoint);\n  }());\n</script>\n',NULL,1,'text/html','2026-09-10 15:43:42','2026-09-10 15:43:42',7,10,'CMS::Template',NULL,NULL,NULL,0),(7,2,2,NULL,'CMS::Template::Version',NULL,NULL,'analytics','{% comment %}\n  Remove the `comment` tags and paste your\n  Google Analytics code down below or replace\n  it all by your custom tracking snippet.\n\n  <script type=\"text/javascript\">\n    var _gaq = _gaq || [];\n    _gaq.push([\'_setAccount\', \'\'UA-YOUR-GOOGLE-ANALYTICS-ID\']);\n    _gaq.push([\'_trackPageview\']);\n\n    (function() {\n      var ga = document.createElement(\'script\'); ga.type = \'text/javascript\'; ga.async = true;\n      ga.src = (\'https:\' == document.location.protocol ? \'https://ssl\' : \'http://www\') + \'.goo