essages_outbox.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_outbox }}\">Sent Messages</a>\n  </li>\n  <li class=\"{% if urls.messages_trash.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_trash }}\">\n      <i class=\"fa fa-trash\"></i>\n      Trash\n    </a>\n  </li>\n</ul>\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,35,'CMS::Template',NULL,'',NULL,0),(34,2,2,NULL,'CMS::Template::Version',NULL,NULL,'messages/menu',NULL,'<ul class=\"nav nav-tabs\">\n  <li class=\"{% if urls.messages_new.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_new }}\">Compose</a>\n  </li>\n  <li class=\"{% if urls.messages_inbox.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_inbox }}\">Inbox</a>\n  </li>\n  <li class=\"{% if urls.messages_outbox.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_outbox }}\">Sent Messages</a>\n  </li>\n  <li class=\"{% if urls.messages_trash.current_or_subpath? %}active{% endif %}\">\n    <a href=\"{{ urls.messages_trash }}\">\n      <i class=\"fa fa-trash\"></i>\n      Trash\n    </a>\n  </li>\n</ul>\n',1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,35,'CMS::Template',NULL,'',NULL,0),(35,2,2,NULL,'CMS::Template::Version',NULL,NULL,'stats/chart','{% content_for stylesheets %}\n  {{ \'stats.css\' | stylesheet_link_tag }}\n  {% cdn_asset /jquery-ui/1.11.4/jquery-ui.css %}\n{% endcontent_for %}\n\n{% content_for javascripts %}\n    {{ \'stats.js\' | javascript_include_tag }}\n{% endcontent_for %}\n\n<div class=\"panel panel-default\">\n  <div class=\"panel-heading\">\n    <i class=\"fa fa-bar-chart\"></i>\n    Graphs\n  {% if provider.multiple_applications_allowed? %}\n      <div id=\"applications-selector-container\" class=\"StatsApplicationsSelectorContainer\">\n          <select id=\"application-select\" name=\"application\">\n              {% assign groups = applications | group_by: \'service\' %}\n              {% for group in groups %}\n                  <optgroup label=\"{{group[0].name}}\">\n                      {% for application in group[1] %}\n                          <option value=\"{{application.id}}\">{{ application.name }}</option>\n                      {% endfor %}\n                  </optgroup>\n              {% endfor %}\n          </select>\n      </div>\n  {% endif %}\n  </div>\n  <div class=\"panel-body\">\n    <div class=\"StatsMenuContainer\" id=\"menu-container\"></div>\n    <div class=\"StatsSelectorContainer\" id=\"selector-container\"></div>\n    <div class=\"StatsChartContainer\" id=\"chart-container\"></div>\n    <p id=\"timezone-info\" data-timezone-identifier=\"{{provider.timezone.identifier}}\" class=\"Stats-message--notice\">\n        Using time zone {{ provider.timezone.full_name }}\n    </p>\n    <div class=\"StatsMethodsTableContainer\" id=\"methods-table-container\"></div>\n  </div>\n  <div class=\"panel-footer\">\n    <div class=\"CsvLinkContainer\" id=\"csv-link-container\"></div>\n  </div>\n</div>\n\n<script type=\"text/javascript\" charset=\"utf-8\">\n  (function() {\n    var applicationGroups = {};\n\n    {% if provider.multiple_applications_allowed? %}\n      /*\n        Gets the service name and application names and ids from the liquid rendered selector\n        Returns an object with the service name as a key, and an array of applications\n        I.E: {\'Echo API\': [{id: 42, name: \'The Answer\'}]}\n       */\n      function applicationGroupsFromSelector () {\n        $(\'.StatsApplicationsSelectorContainer select optgroup\').each(function (_i, group) {\n          let applications = applicationGroups[$(group).attr(\'label\')] = [];\n          $(group).children().each(function (_j, application) {\n            applications.push({id: $(application).val(), name: $(application).html()})\n          })\n        })\n        return applicationGroups;\n      }\n      applicationGroups = applicationGroupsFromSelector()\n    {% endif %}\n\n    Stats.statsApplication(jQuery(\'#client-name\').attr(\'data-client\'),\n      {\n        menuContainer: \'#menu-container\',\n        selectorContainer: \'#selector-container\',\n        chartContainer: \'#chart-container\',\n        methodsTableContainer: \'#methods-table-container\',\n        csvLinkContainer: \'#csv-link-container\',\n        timezone: $(\'#timezone-info\').data(\'timezone-identifier\'),\n        hasApplicationsSelector: Object.keys(applicationGroups).length > 0,\n        applicationGroups: applicationGroups,\n        applicationsSelectorContainer: \'#applications-selector-container\'\n      }\n    );\n\n    })();\n</script>\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,43,'CMS::Template',NULL,'',NULL,0),(36,2,2,NULL,'CMS::Template::Version',NULL,NULL,'stats/chart',NULL,'{% content_for stylesheets %}\n  {{ \'stats.css\' | stylesheet_link_tag }}\n  {% cdn_asset /jquery-ui/1.11.4/jquery-ui.css %}\n{% endcontent_for %}\n\n{% content_for javascripts %}\n    {{ \'stats.js\' | javascript_include_tag }}\n{% endcontent_for %}\n\n<div class=\"panel panel-default\">\n  <div class=\"panel-heading\">\n    <i class=\"fa fa-bar-chart\"></i>\n    Graphs\n  {% if provider.multiple_applications_allowed? %}\n      <div id=\"applications-selector-container\" class=\"StatsApplicationsSelectorContainer\">\n          <select id=\"application-select\" name=\"application\">\n              {% assign groups = applications | group_by: \'service\' %}\n              {% for group in groups %}\n                  <optgroup label=\"{{group[0].name}}\">\n                      {% for application in group[1] %}\n                          <option value=\"{{application.id}}\">{{ application.name }}</option>\n                      {% endfor %}\n                  </optgroup>\n              {% endfor %}\n          </select>\n      </div>\n  {% endif %}\n  </div>\n  <div class=\"panel-body\">\n    <div class=\"StatsMenuContainer\" id=\"menu-container\"></div>\n    <div class=\"StatsSelectorContainer\" id=\"selector-container\"></div>\n    <div class=\"StatsChartContainer\" id=\"chart-container\"></div>\n    <p id=\"timezone-info\" data-timezone-identifier=\"{{provider.timezone.identifier}}\" class=\"Stats-message--notice\">\n        Using time zone {{ provider.timezone.full_name }}\n    </p>\n    <div class=\"StatsMethodsTableContainer\" id=\"methods-table-container\"></div>\n  </div>\n  <div class=\"panel-footer\">\n    <div class=\"CsvLinkContainer\" id=\"csv-link-container\"></div>\n  </div>\n</div>\n\n<script type=\"text/javascript\" charset=\"utf-8\">\n  (function() {\n    var applicationGroups = {};\n\n    {% if provider.multiple_applications_allowed? %}\n      /*\n        Gets the service name and application names and ids from the liquid rendered selector\n        Returns an object with the service name as a key, and an array of applications\n        I.E: {\'Echo API\': [{id: 42, name: \'The Answer\'}]}\n       */\n      function applicationGroupsFromSelector () {\n        $(\'.StatsApplicationsSelectorContainer select optgroup\').each(function (_i, group) {\n          let applications = applicationGroups[$(group).attr(\'label\')] = [];\n          $(group).children().each(function (_j, application) {\n            applications.push({id: $(application).val(), name: $(application).html()})\n          })\n        })\n        return applicationGroups;\n      }\n      applicationGroups = applicationGroupsFromSelector()\n    {% endif %}\n\n    Stats.statsApplication(jQuery(\'#client-name\').attr(\'data-client\'),\n      {\n        menuContainer: \'#menu-container\',\n        selectorContainer: \'#selector-container\',\n        chartContainer: \'#chart-container\',\n        methodsTableContainer: \'#methods-table-container\',\n        csvLinkContainer: \'#csv-link-container\',\n        timezone: $(\'#timezone-info\').data(\'timezone-identifier\'),\n        hasApplicationsSelector: Object.keys(applicationGroups).length > 0,\n        applicationGroups: applicationGroups,\n        applicationsSelectorContainer: \'#applications-selector-container\'\n      }\n    );\n\n    })();\n</script>\n',1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,43,'CMS::Template',NULL,'',NULL,0),(37,2,2,NULL,'CMS::Template::Version',NULL,NULL,'applications/form','<input type=\"hidden\" id=\"cinstance_plan_id\" name=\"application[plan_id]\" value=\"{{ application.plan.id }}\" />\n\n<fieldset>\n  <div class=\"form-group\" id=\"selected-plan\" data-plan-id=\"{{ application.plan.id }}\">\n    <label class=\"control-label col-md-4\">Plan</label>\n    <div class=\"col-md-6\">\n\n        <p class=\"form-control-static\">\n          <strong id=\'selected-plan-name\'>{{application.plan.name}}</strong>\n          {% if application.can_change_plan? %}\n            <span>› </span>\n            <a href=\"#choose-plan-{{ application.id }}\" id=\"choose-plan-{{application.id}}\">\n              Review/Change\n            </a>\n            {% plan_widget application, wizard: true %}\n            {{ \'/css/plans_widget_overrides.css\' | stylesheet_link_tag }}\n          {% endif %}\n        </p>\n\n    </div>\n  </div>\n</fieldset>\n\n<fieldset>\n  {% for field in application.fields %}\n    {% include \'field\' with field %}\n  {% endfor %}\n</fieldset>\n\n{% include \'new_application_licence\' %}\n\n',NULL,1,NULL,'2026-09-10 15:43:46','2026-09-10 15:43:46',NULL,45,'CMS::Template',NULL,'',NULL,0),(38,2,2,NULL,'CMS::Template::Version',NULL,NULL,'applications/form',NULL,'<input type=\"hidden\" id=\"cinstance_plan_id\" name=\"application[plan_id]\" value=\"{{ application.plan.id }}\" />\n\n<fieldset>\n  <div class=\"form-group\" id=\"selected-plan\" data-plan-id=\"{{ application.plan.id }}\">\n    <label class=\"control-label col-md-4\">Plan</label>\n    <div class=\"col-md-6\">\n\n        <p class=\"form-control-static\">\n          <strong id=\'selected-plan-name\'>{{application.plan.name}}</strong>\n     