/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `email_configurations_tenant_id` BEFORE INSERT ON `email_configurations` FOR EACH ROW BEGIN
  DECLARE master_id numeric;
  IF @disable_triggers IS NULL THEN
    IF NEW.tenant_id IS NULL THEN
      SET master_id = (SELECT id FROM accounts WHERE master)
;
      IF NEW.account_id <> master_id THEN
    SET NEW.tenant_id = NEW.account_id;
END IF;

    END IF;
  END IF;
END */;;
