INSERT INTO `messages` VALUES (1,1,'API System: New Application submission','Dear API Administrator,\n\n\n\nA new user master has signed up for your service Master Service on plan Master Plan. The user\'s details are:\n\n* Name: \n* Email: \n* Organization: Master Account\n* Telephone: \n\n\n\nYou can check current user signups on your API Dashboard at https://master.apps.ocp4.test.rgs.mef.gov.it/p/admin/applications/1.\n\n\nThe API Team\n','sent',NULL,NULL,'2026-09-10 15:33:23','2026-09-10 15:33:23',2,'--- {}\n',NULL,NULL),(2,2,'API System: New Application submission','Dear API Administrator,\n\n\n\nA new user admin has signed up for your service Master Service on plan enterprise. The user\'s details are:\n\n* Name: \n* Email: admin@3scale.apps.ocp4.test.rgs.mef.gov.it\n* Organization: Provider Name\n* Telephone: \n\n\n\nYou can check current user signups on your API Dashboard at https://master.apps.ocp4.test.rgs.mef.gov.it/p/admin/applications/2.\n\n\nThe API Team\n','sent',NULL,NULL,'2026-09-10 15:33:23','2026-09-10 15:33:23',2,'--- {}\n',2,NULL),(3,3,'API System: New Service subscription','Dear API Administrator,\n\nThe user Developer has subscribed to your service test-api on plan Default.\n\nThe user\'s details are:\n\n* Name: John Doe\n* Email: admin+test@3scale.apps.ocp4.test.rgs.mef.gov.it\n* Organization: Developer\n* Telephone: \n\n\n\n\n\nThe API Team\n','sent',NULL,NULL,'2026-09-11 12:50:39','2026-09-11 12:50:39',3,'--- {}\n',2,NULL),(4,3,'API System: New Application submission','Dear API Administrator,\n\n\nThe user Developer has submitted a new application for your API.\n\nThe user\'s details are:\n\n* Name: John Doe\n* Email address: admin+test@3scale.apps.ocp4.test.rgs.mef.gov.it\n* Organization: Developer\n* Telephone: \n\n\n\nThe application\'s details are:\n\n* Application title: test-api\n* Application description:\n\ntest-api\n\n\n\n\n\nThe API Team\n','sent',NULL,NULL,'2026-09-11 12:50:39','2026-09-11 12:50:39',2,'--- {}\n',2,NULL),(5,3,'API System: New Service subscription','Dear API Administrator,\n\nThe user Developer has subscribed to your service test-api-jwt on plan Default.\n\nThe user\'s details are:\n\n* Name: John Doe\n* Email: admin+test@3scale.apps.ocp4.test.rgs.mef.gov.it\n* Organization: Developer\n* Telephone: \n\n\n\n\n\nThe API Team\n','sent',NULL,NULL,'2026-09-11 13:14:44','2026-09-11 13:14:44',3,'--- {}\n',2,NULL),(6,3,'API System: New Application submission','Dear API Administrator,\n\n\nThe user Developer has submitted a new application for your API.\n\nThe user\'s details are:\n\n* Name: John Doe\n* Email address: admin+test@3scale.apps.ocp4.test.rgs.mef.gov.it\n* Organization: Developer\n* Telephone: \n\n\n\nThe application\'s details are:\n\n* Application title: area-jwt-coll\n* Application description:\n\narea-jwt-coll\n\n\n\n\n\nThe API Team\n','sent',NULL,NULL,'2026-09-11 13:14:44','2026-09-11 13:14:44',2,'--- {}\n',2,NULL);
